module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire [WIDTH-1:0] rdata,
    output wire rempty
);


    reg [3:0] wptr_bin, rptr_bin;
    wire [3:0] wgray, rgray;
    reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
    reg [3:0] wptr_gray_sync1, wptr_gray_sync2;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wen(winc && !wfull),
        .waddr(wptr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .ren(rinc && !rempty),
        .raddr(rptr_bin),
        .rdata(rdata)
    );


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
        end else if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end


    assign wgray = (wptr_bin >> 1) ^ wptr_bin;


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end


    assign rgray = (rptr_bin >> 1) ^ rptr_bin;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rgray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wgray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    assign wfull = (wgray[3] != rptr_gray_sync2[3]) &&
                   (wgray[2] != rptr_gray_sync2[2]) &&
                   (wgray[1:0] == rptr_gray_sync2[1:0]);


    assign rempty = (rgray == wptr_gray_sync2);

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wen,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire ren,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wen) begin
            RAM_MEM[waddr] <= wdata;
        end
    end


    always @(posedge rclk) begin
        if (ren) begin
            rdata <= RAM_MEM[raddr];
        end
    end

endmodule

