module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 0) ? s3_green : s1_red;
                s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (p_green && pass_request && (cnt > 8'd10)) begin
                cnt <= 8'd10;
            end else begin
                case (state)
                    idle: cnt <= 8'd10;
                    s1_red: cnt <= (cnt == 0) ? 8'd10 : cnt - 1;
                    s3_green: cnt <= (cnt == 0) ? 8'd60 : cnt - 1;
                    s2_yellow: cnt <= (cnt == 0) ? 8'd5 : cnt - 1;
                    default: cnt <= 8'd10;
                endcase
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(*) begin
        case (state)
            idle: {red, yellow, green} = 3'b000;
            s1_red: {red, yellow, green} = 3'b100;
            s3_green: {red, yellow, green} = 3'b001;
            s2_yellow: {red, yellow, green} = 3'b010;
            default: {red, yellow, green} = 3'b000;
        endcase
    end

    assign clock = cnt;

endmodule

