reg [7:0] abs_divisor;
reg dividend_sign;
reg divisor_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        NEG_DIVISOR <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_sign <= sign ? dividend[7] : 0;
            divisor_sign <= sign ? divisor[7] : 0;
            abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
