                               (dividend_sign ^ divisor_sign) ? (~SR[7:0] + 1) : SR[7:0]};
                end else begin
                    result <= SR;
                end
                res_valid <= 1;
                start_cnt <= 0;
            end else begin

                wire [8:0] sum = SR[15:8] + abs_divisor;
                wire carry_out = sum[8];
                SR <= {sum[7:0], SR[7:1], carry_out};
                cnt <= cnt + 1;
            end
        end
    end
