module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        integer i;
        reg [15:0] remainder;
        reg [15:0] quotient;
        reg [7:0] divisor;

        remainder = 0;
        quotient = 0;
        divisor = b_reg;

        for (i = 0;
 i < 16;
 i = i + 1) begin

            remainder = (remainder << 1) | ((a_reg >> (15 - i)) & 1);

            if (remainder >= divisor) begin
                quotient = (quotient << 1) | 1'b1;
                remainder = remainder - divisor;
            end else begin
                quotient = (quotient << 1) | 1'b0;
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

