module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;


wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = a[N-1] ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] mag_b = b[N-1] ? (~b[N-2:0] + 1) : b[N-2:0];


wire same_sign = (sign_a == sign_b);


reg [N-2:0] res_mag;
reg res_sign;

always @(*) begin
    if (same_sign) begin

        wire [N-1:0] sum_mag = {1'b0, mag_a} + {1'b0, mag_b};
        if (sum_mag > (1 << (N-1)) - 1) begin

            res_sign = sign_a;
            res_mag = (sign_a) ? 0 : (1 << (N-1)) - 1;
        end else begin
            res_sign = sign_a;
            res_mag = sum_mag[N-2:0];
        end
    end else begin

        if (mag_a > mag_b) begin
            res_sign = sign_a;
            res_mag = mag_a - mag_b;
        end else if (mag_b > mag_a) begin
            res_sign = sign_b;
            res_mag = mag_b - mag_a;
        end else begin
            res_sign = 0;
            res_mag = 0;
        end
    end
end


assign res = {res_sign, res_sign ? (~res_mag + 1) : res_mag};

assign c = res;

endmodule

