module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);
    reg [N-1:0] res;
    wire same_sign = (a[N-1] == b[N-1]);


    wire [N-1:0] diff = a - b;


    wire [N-2:0] a_mag = a[N-2:0];
    wire [N-2:0] b_mag = b[N-2:0];
    wire [N-2:0] sum = a_mag + b_mag;
    wire a_gt_b_mag = (a_mag > b_mag);
    wire b_gt_a_mag = (b_mag > a_mag);

    always @(*) begin
        if (same_sign) begin
            res = diff;
        end else begin
            if (a_gt_b_mag) begin
                res[N-1] = a[N-1];
            end else if (b_gt_a_mag) begin
                res[N-1] = ~a[N-1];
            end else begin
                res[N-1] = 0;
            end
            res[N-2:0] = sum;
        end


        if (res == 0) begin
            res[N-1] = 0;
        end
    end

    assign c = res;
endmodule

