module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_reg, b_reg;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] product_mantissa;

    reg [9:0] exponent_sum;

    reg [47:0] product;

    reg guard_bit, round_bit, sticky;


    localparam IDLE = 3'd0;
    localparam INPUT_PROCESSING = 3'd1;
    localparam MULTIPLY = 3'd2;
    localparam NORMALIZE = 3'd3;
    localparam ROUND = 3'd4;
    localparam ADJUST_EXPONENT = 3'd5;
    localparam OUTPUT = 3'd6;

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;

        end else begin
            case (counter)
                IDLE: begin
                    counter <= INPUT_PROCESSING;
                    a_reg <= a;
                    b_reg <= b;
                end
                INPUT_PROCESSING: begin

                    a_sign <= a_reg[31];
                    b_sign <= b_reg[31];
                    a_exponent <= a_reg[30:23];
                    b_exponent <= b_reg[30:23];
                    a_mantissa <= a_reg[22:0];
                    b_mantissa <= b_reg[22:0];
                    counter <= MULTIPLY;
                end
                MULTIPLY: begin

                    product_mantissa <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                    exponent_sum <= a_exponent + b_exponent;
                    counter <= NORMALIZE;
                end
                NORMALIZE: begin

                    if (product_mantissa[47]) begin
                        product <= product_mantissa >> 1;
                        exponent_sum <= exponent_sum + 1;
                    end else begin
                        product <= product_mantissa;
                    end
                    counter <= ROUND;
                end
                ROUND: begin

                    guard_bit <= product[42];
                    round_bit <= product[41];
                    sticky <= |product[40:0];
                    counter <= ADJUST_EXPONENT;
                end
                ADJUST_EXPONENT: begin

                    if (guard_bit && (round_bit || sticky)) begin

                        if (product[45:23] + 1 == 24'h100000) begin 
                            product[45:23] <= 23'b0;
                            exponent_sum <= exponent_sum + 1;
                        end else begin
                            product[45:23] <= product[45:23] + 1;
                        end
                    end

                    if (exponent_sum > 255) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                    end else if (exponent_sum == 0) begin

                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin

                        z <= {a_sign ^ b_sign, exponent_sum[7:0], product[45:23]};
                    end
                    counter <= OUTPUT;
                end
                OUTPUT: begin

                    counter <= IDLE;
                end
                default: counter <= IDLE;
            endcase
        end
    end

endmodule

