module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);


localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;

reg [1:0] current_state, next_state;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        S0: next_state = (data_in) ? S0 : S1;
        S1: next_state = (data_in) ? S2 : S0;
        S2: next_state = S0;
        default: next_state = S0;
    endcase
end


assign data_out = (next_state == S0) && (data_in == 0);

endmodule

