module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 3) state <= s3_green;
                s3_green: if (cnt == 3) state <= s2_yellow;
                s2_yellow: if (cnt == 3) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else if (state == s1_red) begin
                if (cnt != 3) cnt <= cnt - 1;
            end else if (state == s3_green) begin
                if (cnt != 3) cnt <= cnt - 1;
            end else if (state == s2_yellow) begin
                if (cnt != 3) cnt <= cnt - 1;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= (state == s1_red) ? 1'b1 : p_red;
            p_yellow <= (state == s2_yellow) ? 1'b1 : p_yellow;
            p_green <= (state == s3_green) ? 1'b1 : p_green;
        end
    end

endmodule

