module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg processing;
    reg [4:0] cnt;
    reg [16:0] sr;

    reg [7:0] divisor_abs;
    reg quotient_sign;
    reg remainder_sign;
    reg [7:0] dividend_abs;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            processing <= 0;
            cnt <= 0;
            sr <= 0;
            divisor_abs <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
            dividend_abs <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                dividend_abs <= sign && dividend[7] ? (~dividend + 1) : dividend;
                divisor_abs <= sign && divisor[7] ? (~divisor + 1) : divisor;
                quotient_sign <= (dividend[7] ^ divisor[7]) && sign;
                remainder_sign <= dividend[7] && sign;
                sr <= {dividend_abs, 8'b0} << 1;
                processing <= 1;
                cnt <= 1;
                res_valid <= 0;
            end else if (processing) begin
                if (cnt == 8) begin
                    reg [7:0] final_quotient = sr[8:1];
                    reg [7:0] final_remainder = sr[16:9];
                    if (quotient_sign) final_quotient = -final_quotient;
                    if (remainder_sign) final_remainder = -final_remainder;
                    result <= {final_remainder, final_quotient};
                    processing <= 0;
                    res_valid <= 1;
                end else begin
                    wire [8:0] sub_result = sr[16:8] - divisor_abs;
                    if (sub_result[8]) begin
                        sr[0] <= 1'b0;
                    end else begin
                        sr[16:9] <= sub_result[7:0];
                        sr[0] <= 1'b1;
                    end
                    sr <= sr << 1;
                    cnt <= cnt + 1;
                end
            end
            if (res_valid && opn_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

