module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-1:0] mag_a = sign_a ? (~a + 1) : a;
wire [N-1:0] mag_b = sign_b ? (~b + 1) : b;

always @(*) begin
    if (sign_a == sign_b) begin
        res = {sign_a, mag_a + mag_b};
    end else begin
        if (mag_a > mag_b) begin
            res = {sign_a, mag_a - mag_b};
        end else if (mag_b > mag_a) begin
            res = {sign_b, mag_b - mag_a};
        end else begin
            res = {1'b0, {(N-1){1'b0}}};
        end
    end
end

assign c = res;

endmodule

