module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c,
    output reg [N-1:0] res
);

reg sign_a, sign_b;
reg [N-2:0] mag_a, mag_b;
reg [N-2:0] res_mag;
reg res_sign;

always @* begin
    sign_a = a[N-1];
    mag_a = a[N-2:0];
    sign_b = b[N-1];
    mag_b = b[N-2:0];

    if (sign_a == sign_b) begin

        if (mag_a >= mag_b) begin
            res_mag = mag_a - mag_b;
            res_sign = sign_a;
        end else begin
            res_mag = mag_b - mag_a;
            res_sign = sign_a;
        end
    end else begin

        if (sign_a) begin

            res_mag = mag_a + mag_b;

            res_sign = (mag_b > mag_a) ? 1'b0 : 1'b1;
        end else begin

            res_mag = mag_a + mag_b;

            res_sign = (mag_a > mag_b) ? 1'b0 : 1'b1;
        end
    end


    if (res_mag == 0) begin
        res_sign = 1'b0;
    end

    res = {res_sign, res_mag};
    c = res;
end

endmodule

