module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [23:0] z_mantissa;
    reg [9:0] z_exponent;
    reg product_sign;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;


    localparam IDLE  = 3'b000;
    localparam EX    = 3'b001;
    localparam ML    = 3'b010;
    localparam NR    = 3'b011;
    localparam RN    = 3'b100;
    localparam OFU   = 3'b101;

    always @(posedge clk) begin
        if (rst) begin
            counter <= IDLE;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            z_mantissa <= 0;
            z_exponent <= 0;
            product_sign <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                IDLE: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];


                    a_mantissa <= (a_exponent == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b_exponent == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin
                        if (a_exponent == 8'hff && b_exponent == 8'hff) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                        end else if (a_exponent == 8'hff) begin

                            if (b_exponent == 8'h00 && b[22:0] == 0) begin
                                z <= {1'b0, 8'hff, 23'h000001};

                            end else begin
                                z <= {a_sign, 8'hff, 23'd0};
                            end
                        end else begin

                            if (a_exponent == 8'h00 && a[22:0] == 0) begin
                                z <= {1'b0, 8'hff, 23'h000001};

                            end else begin
                                z <= {b_sign, 8'hff, 23'd0};
                            end
                        end
                        counter <= IDLE;
                    end else if ((a_exponent == 0 && a[22:0] == 0) || (b_exponent == 0 && b[22:0] == 0)) begin

                        if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                            z <= {1'b0, 8'hff, 23'h000001};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'd0, 23'd0};
                        end
                        counter <= IDLE;
                    end else begin
                        product_sign <= a_sign ^ b_sign;

                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= ML;
                    end
                end

                ML: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= NR;
                end

                NR: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= RN;
                end

                RN: begin


                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];


                    if (guard_bit) begin
                        if (round_bit || sticky || (z_mantissa[0])) begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end


                    if (z_exponent > 254) begin
                        z <= {product_sign, 8'hff, 23'd0};
                    end else if (z_exponent == 0) begin
                        z <= {product_sign, 8'h00, z_mantissa[22:0]};
                    end else begin
                        z <= {product_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= IDLE;
                end

                default: counter <= IDLE;
            endcase
        end
    end
