    assign overflow = ((a_sign == 1'b0 && b_sign == 1'b1 && result_sign == 1'b1) ||
                      (a_sign == 1'b1 && b_sign == 1'b0 && result_sign == 1'b0)) ? 1'b1 : 1'b0;

