module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


localparam [1:0] idle      = 2'b00,
                 s1_red    = 2'b01,
                 s2_yellow = 2'b10,
                 s3_green  = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

assign clock = cnt;
assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) state <= idle;
    else case (state)
        idle:     state <= s1_red;
        s1_red:   state <= (cnt == 0) ? s3_green : s1_red;
        s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
        s2_yellow:state <= (cnt == 0) ? s1_red : s2_yellow;
        default:  state <= idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) cnt <= 10;
    else begin
        if (pass_request && green) cnt <= 10;
        else if (!green && p_green) cnt <= 60;
        else if (!yellow && p_yellow) cnt <= 5;
        else if (!red && p_red) cnt <= 10;
        else cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= (state == s1_red);
        p_yellow <= (state == s2_yellow);
        p_green <= (state == s3_green);
    end
end

endmodule

