code:
module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
);


parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;


reg [31:0] res;
wire [32:0] add_sum, addu_sum, sub_diff, subu_diff;
wire signed [31:0] a_signed = a;
wire signed [31:0] b_signed = b;

always @(*) begin
    case (aluc)
        ADD: begin
            add_sum = {1'b0, a} + {1'b0, b};
            res = add_sum[31:0];
            carry = add_sum[32];
            overflow = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            addu_sum = {1'b0, a} + {1'b0, b};
            res = addu_sum[31:0];
            carry = addu_sum[32];
            overflow = 0;
        end
        SUB: begin
            sub_diff = {1'b0, a} - {1'b0, b};
            res = sub_diff[31:0];
            carry = sub_diff[32];
            overflow = (a[31] != b[31]) && (res[31] == b[31]);
        end
        SUBU: begin
            subu_diff = {1'b0, a} - {1'b0, b};
            res = subu_diff[31:0];
            carry = subu_diff[32];
            overflow = 0;
        end
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: res = (a_signed < b_signed) ? 32'd1 : 32'd0;
        SLTU: res = (a < b) ? 32'd1 : 32'd0;
        SLL: res = a << b[4:0];
        SRL: res = a >> b[4:0];
        SRA: res = $signed(a) >>> b[4:0];
        SLLV: res = b << a[4:0];
