    reg div_sign_final;
    reg [8:0] neg_divisor;
    reg [8:0] sub_result;
    reg carry_out;
    reg [7:0] quotient_bit;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            sr <= 0;
            quotient_reg <= 0;
            remainder_reg <= 0;
            div_sign <= 0;
            div_sign_final <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
