module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    integer i;
    reg [15:0] rem = 16'b0;
    reg [15:0] quo = 16'b0;
    reg [15:0] div = a_reg;

    for (i = 0;
 i < 16;
 i = i + 1) begin

        rem = (rem << 1) | (div >> 15);


        if (rem[15:8] >= b_reg) begin
            rem[15:8] = rem[15:8] - b_reg;
            quo = (quo << 1) | 1'b1;
        end else begin
            quo = (quo << 1) | 1'b0;
        end


        div = div << 1;
    end

    result = quo;
    odd = rem;
end

endmodule

