            multiplicand <= multiplicand << 1;

            if (multiplier[ctr]) begin
                p <= p + multiplicand;
            end
            ctr <= ctr + 1;

            if (ctr == 15) begin
                rdy <= 1'b1;
            end else begin
                rdy <= 1'b0;
            end
        end else begin

            rdy <= 1'b1;
        end
    end
end

