reg [STAGES:0] enable_pipe;
reg [63:0] adda_pipe [STAGES:0];
reg [63:0] addb_pipe [STAGES:0];
reg [31:0] lower_sum [STAGES:0];
reg [31:0] upper_sum [STAGES:0];
reg [31:0] carry [STAGES:0];

integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin

        for (i = 0;
 i <= STAGES;
 i = i + 1) begin
            enable_pipe[i] <= 0;
            adda_pipe[i] <= 0;
            addb_pipe[i] <= 0;
            lower_sum[i] <= 0;
            upper_sum[i] <= 0;
            carry[i] <= 0;
        end
        result <= 0;
        o_en <= 0;
    end else begin

        enable_pipe[0] <= i_en;
        for (i = 1;
 i <= STAGES;
 i = i + 1) begin
            enable_pipe[i] <= enable_pipe[i-1];
        end


        adda_pipe[0] <= adda;
        addb_pipe[0] <= addb;
        {carry[0], lower_sum[0]} <= {adda[31:0] + addb[31:0]};


        for (i = 1;
 i <= STAGES;
 i = i + 1) begin
            adda_pipe[i] <= adda_pipe[i-1];
            addb_pipe[i] <= addb_pipe[i-1];
        end
        upper_sum[1] <= adda_pipe[1][63:32] + addb_pipe[1][63:32] + carry[0];
        carry[1] <= (adda_pipe[1][63:32] + addb_pipe[1][63:32] + carry[0]) >> 32;


        result <= {carry[1], upper_sum[1], lower_sum[0]};


        o_en <= enable_pipe[STAGES];
    end
end

endmodule

