module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

localparam MAX_MAG = (1 << (N-1)) - 1;
localparam MAX_POS = (1 << (N-1)) - 1;

wire [N-1:0] mag_a = a[N-1] ? (MAX_MAG - (a & MAX_POS)) : a;
wire [N-1:0] mag_b = b[N-1] ? (MAX_MAG - (b & MAX_POS)) : b;

wire sign_a = a[N-1];
wire sign_b = b[N-1];

reg [N-1:0] res;

always @* begin
    if (sign_a == sign_b) begin
        reg [N:0] sum_mag;
        sum_mag = mag_a + mag_b;
        if (sum_mag > MAX_MAG)
            res = {sign_a, MAX_MAG};
        else
            res = {sign_a, sum_mag[N-1:0]};
    end else begin
        if (mag_a > mag_b)
            res = {sign_a, mag_a - mag_b};
        else
            res = {sign_b, mag_b - mag_a};
    end
end

assign c = res;

endmodule

