module fixed_point_subtractor #(
    parameter Q = 1,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a - b;

        if (res == 0)
            res[N-1] = 1'b0;
        else
            res[N-1] = a[N-1];
    end else begin

        reg [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
        reg [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;
        reg [N-1:0] sum = abs_a + abs_b;
        reg [N-1:0] diff;
        reg sign;

        if (sum == 0) begin
            res = 0;
        end else if (abs_a > abs_b) begin
            diff = abs_a - abs_b;
            sign = 0;
        end else begin
            diff = abs_b - abs_a;
            sign = 1;
        end

        res = {sign, diff[N-2:0]};
    end
    c = res;
end

endmodule

