module width_8to16 (
    input        clk,
    input        rst_n,
    input        valid_in,
    input  [7:0] data_in,
    output       valid_out,
    output [15:0] data_out
);

    reg [7:0] data_lock;
    reg has_data;
    reg [15:0] data_out_reg;
    reg valid_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_lock    <= 8'b0;
            has_data     <= 1'b0;
            data_out_reg <= 16'b0;
            valid_out_reg<= 1'b0;
        end else begin
            valid_out_reg <= 1'b0;
            if (valid_in) begin
                if (has_data) begin
                    data_out_reg <= {data_lock, data_in};
                    valid_out_reg<= 1'b1;
                    data_lock    <= 8'b0;
                    has_data     <= 1'b0;
                end else begin
                    data_lock <= data_in;
                    has_data  <= 1'b1;
                end
            end
        end
    end

    assign valid_out = valid_out_reg;
    assign data_out  = data_out_reg;

