module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output tri flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [31:0] res;
reg [32:0] add_sum;
reg [32:0] sub_diff;
reg carry_val;
reg overflow_val;

always @(*) begin
    case (aluc)
        ADD: begin
            add_sum = {1'b0, a} + {1'b0, b};
            res = add_sum[31:0];
            carry_val = add_sum[32];
            overflow_val = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            add_sum = {1'b0, a} + {1'b0, b};
            res = add_sum[31:0];
            carry_val = add_sum[32];
            overflow_val = 0;
        end
        SUB: begin
            sub_diff = {1'b0, a} - {1'b0, b};
            res = sub_diff[31:0];
            carry_val = sub_diff[32];
            overflow_val = (a[31] != b[31]) && (res[31] != a[31]);
        end
        SUBU: begin
            sub_diff = {1'b0, a} - {1'b0, b};
            res = sub_diff[31:0];
            carry_val = sub_diff[32];
            overflow_val = 0;
        end
        AND:  res = a & b;
        OR:   res = a | b;
        XOR:  res = a ^ b;
        NOR:  res = ~(a | b);
        SLT:  res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        SLTU: res = (a < b) ? 32'd1 : 32'd0;
        SLL:  res = a << b[4:0];
        SRL:  res = a >> b[4:0];
        SRA:  res = $signed(a) >>> b[4:0];
        SLLV: res = a << a[4:0];
        SRLV: res = a >> a[4:0];
        SRAV: res = $signed(a) >>> a[4:0];
        LUI:  res = {a[31:16], 16'b0};

        default: res = 32'bz;
    endcase
end

assign r = res;
assign zero = (res == 32'd0);
assign negative = res[31];
assign carry = (aluc inside {ADD, ADDU, SUB, SUBU}) ? carry_val : 1'b0;
assign overflow = (aluc inside {ADD, SUB}) ? overflow_val : 1'b0;
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

