module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg [7:0] neg_divisor;
reg [15:0] SR;
reg [3:0] cnt;
reg start;
reg dividend_sign;
reg divisor_sign;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        SR <= 0;
        cnt <= 0;
        start <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        neg_divisor <= 0;
    end else begin
        if (res_valid) begin
            res_valid <= 0;
        end

        if (!res_valid && opn_valid) begin

            dividend_sign <= sign ? dividend[7] : 1'b0;
            divisor_sign <= sign ? divisor[7] : 1'b0;

            if (sign) begin
                dividend_abs <= (dividend[7]) ? -dividend : dividend;
                divisor_abs <= (divisor[7]) ? -divisor : divisor;
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
            end

            neg_divisor <= -divisor_abs;


            SR <= {7'b0, dividend_abs, 1'b0};
            cnt <= 4'd1;
            start <= 1'b1;
        end

        if (start) begin
            if (cnt < 8) begin

                wire [8:0] temp_sum = SR[15:8] + divisor_abs;
                wire carry_out = temp_sum[8];

                if (carry_out) begin

                    SR[15:8] <= temp_sum[7:0];
                    SR <= {temp_sum[7:0], SR[7:1], carry_out};
                end else begin

                    SR <= {SR[14:8], 8'b0, 1'b0};
                end

                cnt <= cnt + 1;
            end else begin

                start <= 0;
                dividend_sign <= dividend_sign;
                divisor_sign <= divisor_sign;
                res_valid <= 1;


                if (sign) begin

                    result[15:8] <= dividend_sign ? -SR[15:8] : SR[15:8];

                    result[7:0] <= (dividend_sign ^ divisor_sign) ? -SR[7:0] : SR[7:0];
                end else begin
                    result <= {SR[15:8], SR[7:0]};
                end
            end
        end
    end
end

endmodule

