                if (count_reg == 2'd3) begin
                    data_out <= sum_reg + data_in;
                    valid_out <= 1'b1;
                    sum_reg <= 10'b0;
                    count_reg <= 2'b0;
                end else begin
                    sum_reg <= sum_reg + data_in;
                    count_reg <= count_reg + 1;
                end
            end
        end
    end

endmodule

