module fixed_point_adder #(
    parameter Q = 1,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);


wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

wire a_gt_b = (a_abs > b_abs);
wire [N-1:0] diff = a_gt_b ? (a_abs - b_abs) : (b_abs - a_abs);
wire sign_diff = a_gt_b ? sign_a : (a_abs == b_abs ? 1'b0 : sign_b);

reg [N-1:0] res;

always @(*) begin
    if (same_sign) begin
        res = a + b;
    end else begin
        res = {sign_diff, diff};
    end
end

assign c = res;

endmodule

