module fixed_point_subtractor #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] mag_a, mag_b;
    wire [N-1:0] sum;

    always @* begin
        if (sign_a == sign_b) begin
            res = a - b;

            res[N-1] = sign_a;
        end else begin

            mag_a = sign_a ? (~a + 1) : a;
            mag_b = sign_b ? (~b + 1) : b;
            sum = mag_a + mag_b;

            res[N-1] = (mag_a >= mag_b) ? 1'b0 : 1'b1;

            res[N-2:0] = sum[N-2:0];
        end

        if (res == 0)
            res[N-1] = 1'b0;
    end

    assign c = res;

endmodule

