module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam IDLE = 2'b00;
    localparam WAIT_FOR_1 = 2'b01;
    localparam DETECTED = 2'b10;

    reg [1:0] current_state, next_state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            current_state <= IDLE;
            data_out <= 0;
        end else begin
            current_state <= next_state;
            case (current_state)
                IDLE: data_out <= 0;
                WAIT_FOR_1: data_out <= 0;
                DETECTED: data_out <= (data_in == 0) ? 1'b1 : 1'b0;
                default: data_out <= 0;
            endcase
        end
    end

    always @(*) begin
        case (current_state)
            IDLE: next_state = (data_in == 0) ? WAIT_FOR_1 : IDLE;
            WAIT_FOR_1: next_state = (data_in == 1) ? DETECTED : IDLE;
            DETECTED: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

endmodule

