module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output tri flag
);

parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

wire signed [31:0] a_signed = a;
wire signed [31:0] b_signed = b;
wire [31:0] a_unsigned = a;
wire [31:0] b_unsigned = b;

assign zero = (r == 32'b0);
assign negative = r[31];

wire slt_flag = ($signed(a_signed) < $signed(b_signed));
wire sltu_flag = (a_unsigned < b_unsigned);

assign flag = (aluc == SLT) ? slt_flag :
              (aluc == SLTU) ? sltu_flag :
              1'bz;

always @(*) begin

    r = 32'b0;
    carry = 1'b0;
    overflow = 1'b0;

    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a_signed[31] == b_signed[31]) && (r[31] != a_signed[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = 1'b0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a_signed[31] != b_signed[31]) && (r[31] != a_signed[31]);
            carry = ~carry;
        end
        SUBU: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = 1'b0;
            carry = ~carry;
        end
        AND: begin
            r = a & b;
            carry = 1'b0;
            overflow = 1'b0;
        end
        OR: begin
            r = a | b;
            carry = 1'b0;
            overflow = 1'b0;
        end
        XOR: begin
            r = a ^ b;
            carry = 1'b0;
            overflow = 1'b0;
        end
        NOR: begin
            r = ~(a | b);
            carry = 1'b0;
            overflow = 1'b0;
        end
        SLT: begin
            r = ($signed(a_signed) < $signed(b_signed)) ? 32'd1 : 32'd0;
            carry = 1'b0;
            overflow = 1'b0;
        end
        SLTU: begin
            r = (a_unsigned < b_unsigned) ? 32'd1 : 32'd0;
            carry = 1'b0;
            overflow = 1'b0;
        end
        SLL: begin
            r = b << a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        SRL: begin
            r = b >> a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        SRA: begin
            r = $signed(b_signed) >>> a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        SLLV: begin
            r = b << a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        SRLV: begin
            r = b >> a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        SRAV: begin
            r = $signed(b_signed) >>> a[4:0];
            carry = 1'b0;
            overflow = 1'b0;
        end
        LUI: begin
            r = a << 16;
            carry = 1'b0;
            overflow = 1'b0;
        end
        default: begin
            r = 32'bz;
            carry = 1'b0;
            overflow = 1'b0;
        end
    endcase
end

endmodule

