module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg div_sign, divsor_sign;
reg [8:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [8:0] NEG_DIVISOR;
reg [7:0] quotient, remainder;
reg [7:0] quotient_final, remainder_final;

wire [8:0] sub_result = SR - NEG_DIVISOR;
wire carry_out = ~sub_result[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        NEG_DIVISOR <= 0;
        quotient <= 0;
        remainder <= 0;
        result <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_abs <= sign ? (-dividend) : dividend;
            divisor_abs <= sign ? (-divisor) : divisor;
            div_sign <= sign ? dividend[7] : 0;
            divsor_sign <= sign ? divisor[7] : 0;
            SR <= {1'b0, dividend_abs} << 1;

            NEG_DIVISOR <= -{1'b0, divisor_abs};

            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin
                if (carry_out) begin
                    SR <= sub_result;
                    quotient <= {quotient[6:0], 1'b1};
                end else begin
                    quotient <= {quotient[6:0], 1'b0};
                end
                cnt <= cnt + 1;
            end else begin

                if (carry_out) begin
                    SR <= sub_result;
                    quotient <= {quotient[6:0], 1'b1};
                end else begin
                    quotient <= {quotient[6:0], 1'b0};
                end
                remainder <= SR[8:1];

                quotient_final <= (div_sign ^ divsor_sign) ? -quotient : quotient;
                remainder_final <= div_sign ? -remainder : remainder;


                result <= {remainder_final, quotient_final};
                start_cnt <= 0;
                res_valid <= 1;
            end
        end
        if (res_valid && !opn_valid) res_valid <= 0;
    end
end

endmodule

