assign borrow[0] = (A[0] < B[0]);


assign diff[1] = A[1] - B[1] - borrow[0];
assign borrow[1] = (A[1] < (B[1] + borrow[0]));


assign diff[2] = A[2] - B[2] - borrow[1];
assign borrow[2] = (A[2] < (B[2] + borrow[1]));


assign diff[3] = A[3] - B[3] - borrow[2];
assign borrow[3] = (A[3] < (B[3] + borrow[2]));

assign A_less = borrow[3];
assign A_equal = (diff == 4'b0);
assign A_greater = ~borrow[3] & (diff != 4'b0);

