module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire [N-1:0] a_abs = a[N-1] ? (~a + 1) : a;
    wire [N-1:0] b_abs = b[N-1] ? (~b + 1) : b;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);

    reg [N-1:0] sum_abs;
    reg res_sign;

    always @(*) begin
        if (same_sign) begin
            sum_abs = a_abs + b_abs;
            res_sign = a_sign;
        end else begin
            if (a_abs > b_abs) begin
                sum_abs = a_abs - b_abs;
                res_sign = a_sign;
            end else if (b_abs > a_abs) begin
                sum_abs = b_abs - a_abs;
                res_sign = b_sign;
            end else begin
                sum_abs = 0;
                res_sign = 0;
            end
        end


        if (sum_abs > (2**(N-1)-1)) begin
            sum_abs = 2**(N-1)-1;
        end

        res = {res_sign, sum_abs[N-2:0]};
    end

    assign c = res;

endmodule

