module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;

    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'd0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];


                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a[30:23] == 8'hff && a[22:0] != 0) || 
                        (b[30:23] == 8'hff && b[22:0] != 0)) begin
                        z <= {a_sign, 8'hff, a[22:0]};

                    end else if ((a[30:23] == 8'hff && (b[30:23] == 0 || b[30:23] == 8'hff)) ||  
                                 (b[30:23] == 8'hff && (a[30:23] == 0 || a[30:23] == 8'hff))) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                    end else if ((a[30:23] == 0 && a[22:0] == 0) || (b[30:23] == 0 && b[22:0] == 0)) begin

                        if ((a[30:23] == 0 && b[30:23] != 0 && b[22:0] != 0) || 
                            (b[30:23] == 0 && a[30:23] != 0 && a[22:0] != 0)) begin
                            z <= {a_sign ^ b_sign, 31'd0};

                        end else begin
                            z <= {1'b0, 31'd0};

                        end
                    end else begin

                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
