wire full_cond = (wptr_gray[PTR_WIDTH-1] != rptr_syn_gray[1][PTR_WIDTH-1]) &&
                 (wptr_gray[PTR_WIDTH-2] != rptr_syn_gray[1][PTR_WIDTH-2]) &&
                 (wptr_gray[PTR_WIDTH-3:0] == rptr_syn_gray[1][PTR_WIDTH-3:0]);

