module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'd4;
        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
        EMPTY <= 1'b1;
        FULL <= 1'b0;
    end else if (EN) begin
        reg [2:0] next_SP = SP;
        reg [3:0] next_dataOut = dataOut;
        reg next_EMPTY, next_FULL;

        if (RW == 1'b0) begin 
            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;
                next_SP = SP - 1;
            end
        end else begin 
            if (!EMPTY) begin
                next_dataOut = stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                next_SP = SP + 1;
            end
        end

        SP <= next_SP;
        dataOut <= next_dataOut;
        next_EMPTY = (next_SP == 3'd4);
        next_FULL = (next_SP == 3'd0);
        EMPTY <= next_EMPTY;
        FULL <= next_FULL;
    end
end

endmodule

