    if (!rst_n) begin
        data_lock <= 8'b0;
        flag <= 0;
        data_out <= 16'b0;
        valid_out <= 0;
    end else begin

        valid_out <= 0;

        if (flag) begin
            if (valid_in) begin
                data_out <= {data_lock, data_in};
                valid_out <= 1;
                flag <= 0;
            end
        end else begin
            if (valid_in) begin
                data_lock <= data_in;
                flag <= 1;
            end
        end
    end
end

