module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg sign_a, sign_b;
reg [N-2:0] mag_a, mag_b;
reg [N-1:0] sum_mag;
reg [N-2:0] sub_mag;
reg sign_res, mag_res;

always @(*) begin
    sign_a = a[N-1];
    mag_a = a[N-2:0];
    sign_b = b[N-1];
    mag_b = b[N-2:0];
    sum_mag = mag_a + mag_b;

    if (sign_a == sign_b) begin
        if (sum_mag >= (1 << (N-1))) begin
            mag_res = (1 << (N-1)) - 1;
            sign_res = sign_a;
        end else begin
            mag_res = sum_mag[N-2:0];
            sign_res = sign_a;
        end
    end else begin
        if (mag_a > mag_b) begin
            sub_mag = mag_a - mag_b;
            sign_res = sign_a;
        end else if (mag_b > mag_a) begin
            sub_mag = mag_b - mag_a;
            sign_res = sign_b;
        end else begin
            sub_mag = 0;
            sign_res = 0;
        end
        mag_res = sub_mag;
    end

    c = {sign_res, mag_res};
end

endmodule

