module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);
    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] absolute_b, absolute_a;
    reg [N-1:0] temp;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        res = 0;
        temp = 0;
        absolute_b = 0;
        absolute_a = 0;

        if (sign_a == sign_b) begin

            res = a - b;

            res[N-1] = sign_a;
        end else begin

            if (sign_a == 1'b0) begin

                absolute_b = ~b + 1;
                temp = a + absolute_b;
                if (a >= absolute_b) begin
                    res = temp;
                    res[N-1] = 0;
                end else begin
                    res = temp;
                    res[N-1] = 1;
                end
            end else begin

                absolute_b = ~b + 1;
                temp = a - absolute_b;
                absolute_a = ~a + 1;
                if (absolute_a >= absolute_b) begin
                    res = temp;
                    res[N-1] = 1;
                end else begin
                    res = temp;
                    res[N-1] = 0;
                end
            end
        end


        if (res == 0) begin
            res[N-1] = 0;
        end

        c = res;
    end
endmodule

