module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [8:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa, z_mantissa;
reg [49:0] product;
reg guard, round, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)

            3'b000: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};

                if ((a_exponent == 9'h1FF && (a[30:23] != 8'hFF || a[22:0] != 0)) ||
                    (b_exponent == 9'h1FF && (b[30:23] != 8'hFF || b[22:0] != 0))) begin

                    if (a[30:0] == 31'h7FF00000 || b[30:0] == 31'h7FF00000) begin
                        z <= {1'b0, 8'hFF, 23'h1};

                    end else begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {1'b0, 8'hFF, 23'h0};

                    end
                    counter <= 3'b100;
                end else if ((a_exponent == 9'h0 && a_mantissa == 24'h0) || 
                             (b_exponent == 9'h0 && b_mantissa == 24'h0)) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {1'b0, 8'h0, 23'h0};

                    counter <= 3'b100;
                end else begin
                    product <= a_mantissa * b_mantissa;
                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= a_exponent + b_exponent - 9'd127;
                    counter <= 3'b001;
                end
            end


            3'b001: begin
                if (product[47]) begin
                    product <= product >> 1;
                    z_mantissa <= product[46:24];
                    guard <= product[23];
                    round <= product[22];
                    sticky <= |product[21:0];
                end else begin
                    z_mantissa <= product[47:25];
                    guard <= product[24];
                    round <= product[23];
                    sticky <= |product[22:0];
                end
                counter <= 3'b010;
            end


            3'b010: begin
                if (guard) begin
                    if (round || sticky) begin
                        {z_mantissa, z_exponent} <= z_mantissa + 1;
                        if (z_mantissa + 1 == 24'h1000000) begin
                            z_exponent <= z_exponent + 1;
                            z_mantissa <= 23'h0;
                        end
                    end
                end


                if (z_exponent >= 9'h1FF) begin
                    z <= {z_sign, 8'hFF, 23'h0};

                end else if (z_exponent < 9'h001) begin
                    z <= {z_sign, 8'h0, 23'h0};

                end else begin
                    z <= {z_sign, z_exponent[7:0], z_mantissa};
                end

                counter <= 3'b000;
            end

            default: counter <= 3'b000;
        endcase
    end
end

endmodule

