module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [7:0] cnt;
reg [1:0] state;
reg [1:0] state_prev;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: state <= (cnt == 0) ? s3_green : s1_red;
            s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_prev <= idle;
    end else begin
        state_prev <= state;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            cnt <= 10;
        end else if (state != state_prev) begin

            case (state)
                s1_red:    cnt <= 3;
                s3_green:  cnt <= 60;
                s2_yellow: cnt <= 5;
                default:   cnt <= 10;
            endcase
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 3'b000;
        {red, yellow, green} <= 3'b000;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;

        case (state)
            idle:      {red, yellow, green} <= 3'b000;
            s1_red:    {red, yellow, green} <= 3'b100;
            s2_yellow: {red, yellow, green} <= 3'b010;
            s3_green:  {red, yellow, green} <= 3'b001;
            default:   {red, yellow, green} <= 3'b000;
        endcase
    end
end

assign clock = cnt;

endmodule

