module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [8:0] NEG_DIVISOR;
reg [15:0] SR;
reg [3:0] cnt;
reg processing;
reg quotient_sign;
reg remainder_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        processing <= 0;
        cnt <= 0;
        SR <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        NEG_DIVISOR <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
        result <= 0;
    end else begin
        if (processing) begin
            if (cnt < 8) begin

                wire [8:0] sub_res = SR[15:7] + abs_divisor;
                wire carry = ~sub_res[8];
                if (carry) begin
                    SR <= {sub_res[7:0], SR[6:0], 1'b1};
                end else begin
                    SR <= {SR[15:7], SR[6:0], 1'b0};
                end
                cnt <= cnt + 1;
            end else begin
                processing <= 0;
                res_valid <= 1;

                if (quotient_sign) begin
                    result[7:0] <= ~SR[6:0] + 1;
                end else begin
                    result[7:0] <= SR[6:0];
                end
                if (remainder_sign) begin
                    result[15:8] <= ~SR[15:8] + 1;
                end else begin
                    result[15:8] <= SR[15:8];
                end
            end
        end else if (opn_valid && !res_valid) begin
            res_valid <= 0;
            processing <= 1;
            cnt <= 0;
            abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            quotient_sign <= (sign && (dividend[7] ^ divisor[7]));
            remainder_sign <= sign && dividend[7];
            NEG_DIVISOR <= -abs_divisor;
            SR <= {abs_dividend, 8'b0} << 1;
        end
    end
end

endmodule

