reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    integer i;
    reg [15:0] quotient;
    reg [15:0] remainder;

    quotient = 0;
    remainder = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        remainder = {remainder[14:0], a_reg[i]};
        if (remainder >= b_reg) begin
            remainder = remainder - b_reg;
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

