module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);
    wire b0, b1, b2, b3;
    wire [3:0] diff;


    assign b0 = (~A[0] & B[0]) | ((~A[0] | B[0]) & 1'b0);
    assign b1 = (~A[1] & B[1]) | ((~A[1] | B[1]) & b0);
    assign b2 = (~A[2] & B[2]) | ((~A[2] | B[2]) & b1);
