    assign diff[1] = A[1] ^ B[1] ^ b0;
    assign diff[2] = A[2] ^ B[2] ^ b1;
    assign diff[3] = A[3] ^ B[3] ^ b2;


    assign A_equal = (diff == 4'b0000);
    assign A_greater = ~b3 & ~A_equal;
    assign A_less = b3;
