module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output G,
    output P
);
    wire [16:1] P_bit = A ^ B;
    wire [16:1] G_bit = A & B;
    wire [16:1] C;

    assign C[1] = G_bit[1] | (P_bit[1] & C_in);

    genvar i;
    generate
        for (i = 2;
 i <= 16;
 i = i + 1) begin: carry
            assign C[i] = G_bit[i] | (P_bit[i] & C[i-1]);
        end
    endgenerate

    assign S = A ^ B ^ C;

    assign P = &P_bit;

    wire [16:1] G_acc;
    assign G_acc[1] = G_bit[1];
    genvar j;
    generate
        for (j = 2;
 j <= 16;
 j = j + 1) begin: gen_g_acc
            assign G_acc[j] = G_bit[j] | (P_bit[j] & G_acc[j-1]);
        end
    endgenerate
    assign G = G_acc[16];
endmodule

