module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [9:0] a_exponent, b_exponent, z_exponent;
    reg a_sign, b_sign, z_sign;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] round_mantissa;
    reg [9:0] round_exponent;
    reg is_nan, is_inf, is_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            z_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            is_nan <= 0;
            is_inf <= 0;
            is_zero <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                1: begin

                    is_nan <= ( (a_exponent == 9'hff && a_mantissa[22:0] != 0) || (b_exponent == 9'hff && b_mantissa[22:0] != 0) );
                    is_inf <= ( (a_exponent == 9'hff && (a_mantissa[22:0] == 0)) || (b_exponent == 9'hff && (b_mantissa[22:0] == 0)) );
                    is_zero <= ( (a_exponent == 9'h0 && a_mantissa[22:0] == 0) || (b_exponent == 9'h0 && b_mantissa[22:0] == 0) );
                    if (is_nan || is_inf || is_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        if (is_nan) begin
                            z_exponent <= 9'hff;
                            z_mantissa <= 24'h000001;
                        end else if (is_inf) begin
                            z_exponent <= 9'hff;
                            z_mantissa <= 24'h0;
                        end else begin
                            z_exponent <= 9'h0;
                            z_mantissa <= 24'h0;
                        end
                        counter <= 0;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        counter <= counter + 1;
                    end
                end
                2: begin

                    if (product[47:46] >= 2) begin

                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 9'd127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 9'd127;
                    end

                    if (product[47:46] >= 2) begin
                        round_mantissa <= product[46:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end else begin
                        round_mantissa <= product[46:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= counter + 1;
                end
                3: begin


                    if (guard_bit) begin
                        if (round_bit || sticky) begin
                            round_mantissa <= round_mantissa + 1;
                        end else begin
                            if (round_mantissa[0]) begin
                                round_mantissa <= round_mantissa + 1;
                            end
                        end
                    end

                    if (round_mantissa >= 24'h800000) begin
                        round_mantissa <= round_mantissa >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= counter + 1;
                end
                4: begin

                    if (z_exponent >= 9'hfe) begin

                        z_exponent <= 9'hff;
                        z_mantissa <= 24'h0;
                    end else if (z_exponent <= 9'h0) begin

                        z_exponent <= 9'h0;
                        z_mantissa <= 24'h0;
                    end else begin
                        z_mantissa <= round_mantissa;
                    end

                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <= 0;
                end
                default: begin
                    counter <= 0;
                end
            endcase
        end
    end

endmodule

