module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

wire a_sign = A[63];
wire b_sign = B[63];
wire result_sign;

assign result = $signed(A) - $signed(B);
assign result_sign = result[63];

assign overflow = ( (a_sign == 1'b0 && b_sign == 1'b1 && result_sign == 1'b1) ||
                    (a_sign == 1'b1 && b_sign == 1'b0 && result_sign == 1'b0) ) ? 1'b1 : 1'b0;

endmodule

