    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] stack_ptr;
integer i;


always @(*) begin
    EMPTY = (stack_ptr == 3'd0);
    FULL = (stack_ptr == 3'd4);
end

always @(posedge Clk) begin
    if (Rst) begin
        stack_ptr <= 3'd4;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 4'b0;
        end
    end else if (EN) begin
        if (RW) begin

            if (!FULL) begin
                dataOut <= stack_mem[stack_ptr - 1];
                stack_mem[stack_ptr - 1] <= 4'b0;
                stack_ptr <= stack_ptr - 1;
            end
        end else begin

            if (!FULL) begin
                stack_mem[stack_ptr] <= dataIn;
                stack_ptr <= stack_ptr + 1;
            end
        end
    end
end

endmodule

