        valid_out <= 1'b0;

        if (valid_in) begin
            if (has_first) begin
                temp_data <= {data_lock, data_in};
                need_output <= 1'b1;
                has_first <= 1'b0;
            end else begin
                data_lock <= data_in;
                has_first <= 1'b1;
            end
        end else begin
            need_output <= 1'b0;
        end

        if (need_output) begin
            data_out <= temp_data;
            valid_out <= 1'b1;
            need_output <= 1'b0;
        end
    end
end

