module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;

    reg [3:0] cnt;
    reg original_dividend_sign, original_divisor_sign;
    reg quotient_sign, remainder_sign;
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam DIVIDING = 2'b01;
    localparam DONE = 2'b10;

    wire [7:0] comb_abs_dividend = sign ? (dividend[7] ? -dividend : dividend) : dividend;
    wire [7:0] comb_abs_divisor = sign ? (divisor[7] ? -divisor : divisor) : divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            SR <= 0;
            cnt <= 0;
            state <= IDLE;
            original_dividend_sign <= 0;
            original_divisor_sign <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        original_dividend_sign <= dividend[7];
                        original_divisor_sign <= divisor[7];


                        SR <= {comb_abs_dividend, 8'b0} << 1;
                        cnt <= 0;
                        state <= DIVIDING;
                    end
                end
                DIVIDING: begin
                    if (cnt < 8) begin

                        reg [15:0] shifted_SR = SR << 1;
                        reg [7:0] new_remainder = shifted_SR[15:8];
                        reg new_quotient_bit;

                        if (new_remainder >= comb_abs_divisor) begin
                            new_remainder = new_remainder - comb_abs_divisor;
                            new_quotient_bit = 1'b1;
                        end else begin
                            new_quotient_bit = 1'b0;
                        end

                        SR <= {new_remainder, shifted_SR[7:1], new_quotient_bit};
                        cnt <= cnt + 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    res_valid <= 1;
                    quotient_sign <= original_dividend_sign ^ original_divisor_sign;
                    remainder_sign <= original_dividend_sign;


                    if (sign) begin
                        result[15:8] <= remainder_sign ? (~SR[15:8] + 1) : SR[15:8];
                        result[7:0] <= quotient_sign ? (~SR[7:0] + 1) : SR[7:0];
                    end else begin
                        result[15:8] <= SR[15:8];
                        result[7:0] <= SR[7:0];
                    end
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

