module div_16bit (A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        integer i;
        reg [15:0] current_remainder;
        reg [15:0] quotient;

        current_remainder = 16'b0;
        quotient = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            current_remainder = {current_remainder[14:0], a_reg[i]};

            if (current_remainder >= {8'b0, b_reg}) begin
                quotient[i] = 1'b1;
                current_remainder = current_remainder - {8'b0, b_reg};
            end
        end

        result = quotient;
        odd = {8'b0, current_remainder[7:0]};
    end
endmodule

