module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [9:0] accumulator;
reg [1:0] count;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        accumulator <= 10'b0;
        count <= 2'b0;
    end else begin
        if (valid_in) begin
            accumulator <= accumulator + data_in;
            count <= count + 1;
            if (count == 2'd3) begin
                accumulator <= 10'b0;
                count <= 2'b0;
            end
        end
    end
end

assign valid_out = (count == 2'd3) && valid_in;
assign data_out = accumulator + data_in;

endmodule

