    s_a = a[N-1];
    m_a = a[N-2:0];
    s_b = b[N-1];
    m_b = b[N-2:0];

    if (s_a == s_b) begin

        if (s_a == 0) begin

            if (m_a >= m_b) begin
                result_mag = m_a - m_b;
                result_sign = 0;
            end else begin
                result_mag = m_b - m_a;
                result_sign = 1;
            end
        end else begin

            if (m_a >= m_b) begin
                result_mag = m_a - m_b;
                result_sign = 1;
            end else begin
                result_mag = m_b - m_a;
                result_sign = 0;
            end
        end
    end else begin

        if (s_a == 0) begin

            result_mag = m_a + m_b;
            result_sign = (m_a >= m_b) ? 0 : 1;
        end else begin

            result_mag = m_a + m_b;
            result_sign = (m_a >= m_b) ? 1 : 0;
        end
    end


    if (result_mag == 0)
        result_sign = 0;


    c = {result_sign, result_mag};
end

