    reg [23:0] product_mantissa;
    reg [9:0] z_exponent;
    reg [23:0] normalized_product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];

                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if ((a_exponent == 8'hff && b_exponent == 8'hff) || 
                            (a_exponent == 8'hff && a_mantissa != 0) || 
                            (b_exponent == 8'hff && b_mantissa != 0)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
