                3'b1: begin
                    reg [23:0] a_mant, b_mant;
                    a_mant = (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mant = (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    product_mantissa = a_mant * b_mant;

                    integer i;
                    reg found;
                    integer shift_amount;
                    found = 0;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product_mantissa[i]) begin
                            found = 1;
                            shift_amount = 47 - i;
                            break;
                        end
                    end

                    if (found) begin
                        normalized_product = product_mantissa >> shift_amount;
                        z_exponent = a_exponent + b_exponent - 9'h1_00 + shift_amount;
                    end else begin
                        z_exponent = 9'b0;
                        normalized_product = 24'b0;
                    end
                    counter <= 3'b2;
                end

                3'b2: begin
                    reg [47:0] normalized_48bit = {1'b0, normalized_product};
                    guard = 0;
                    round = 0;
                    sticky = 0;

                    if (normalized_48bit[47]) begin
                        guard = normalized_48bit[23];
                        round = normalized_48bit[22];
                        sticky = normalized_48bit[21] | normalized_48bit[20] | normalized_48bit[19] | normalized_48bit[18] | normalized_48bit[17] | normalized_48bit[16] | normalized_48bit[15] | normalized_48bit[14] | normalized_48bit[13] | normalized_48bit[12] | normalized_48bit[11] | normalized_48bit[10] | normalized_48bit[9] | normalized_48bit[8] | normalized_48bit[7] | normalized_48bit[6] | normalized_48bit[5] | normalized_48bit[4] | normalized_48bit[3] | normalized_48bit[2] | normalized_48bit[1] | normalized_48bit[0];
                    end else begin
                        guard = normalized_48bit[46];
                        round = normalized_48bit[45];
                        sticky = normalized_48bit[44] | normalized_48bit[43] | normalized_48bit[42] | normalized_48bit[41] | normalized_48bit[40] | normalized_48bit[39] | normalized_48bit[38] | normalized_48bit[37] | normalized_48bit[36] | normalized_48bit[35] | normalized_48bit[34] | normalized_48bit[33] | normalized_48bit[32] | normalized_48bit[31] | normalized_48bit[30] | normalized_48bit[29] | normalized_48bit[28] | normalized_48bit[27] | normalized_48bit[26] | normalized_48bit[25] | normalized_48bit[24] | normalized_48bit[23] | normalized_48bit[22];
                    end

                    if (guard & (round | sticky) || 
                        (guard && !round && !sticky)) begin
                        if (normalized_product[0] + 1 > 23'h7fffff) begin
                            z_exponent = z_exponent + 1;
                            normalized_product = {1'b0, normalized_product[23:1]} + 1;
                        end else begin
                            normalized_product = normalized_product + 1;
                        end
                    end
                    counter <= 3'b3;
                end

                3'b3: begin
                    if (z_exponent[8]) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (z_exponent[7] == 0) begin
                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], normalized_product[22:0]};
                    end
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end

