module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_green_prev, p_yellow_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_green <= 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_green <= 0;
                        p_yellow <= 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_yellow <= 0;
                        p_red <= 1;
                    end
                end
                default: begin
                    state <= idle;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
            p_red_prev <= 0;
            p_green_prev <= 0;
            p_yellow_prev <= 0;
        end else begin
            p_red_prev <= p_red;
            p_green_prev <= p_green;
            p_yellow_prev <= p_yellow;

            if (pass_request && p_green) begin
                cnt <= 8'd10;
            end else if (!p_green && p_green_prev) begin
                cnt <= 8'd60;
            end else if (!p_yellow && p_yellow_prev) begin
                cnt <= 8'd5;
            end else if (!p_red && p_red_prev) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end


    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

endmodule

