module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg original_dividend_sign;
    reg original_divisor_sign;
    reg signed [7:0] NEG_DIVISOR;
    reg [15:0] SR_reg;
    reg [3:0] cnt;
    reg start_cnt;
    reg is_signed;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR_reg <= 0;
            cnt <= 0;
            start_cnt <= 0;
            is_signed <= 0;
            original_dividend_sign <= 0;
            original_divisor_sign <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                original_dividend_sign <= dividend[7];
                original_divisor_sign <= divisor[7];
                dividend_abs <= sign ? -dividend : dividend;
                divisor_abs <= sign ? -divisor : divisor;
                NEG_DIVISOR <= sign ? -divisor : -divisor;
                SR_reg <= {dividend_abs, 8'b0} << 1;
                cnt <= 0;
                start_cnt <= 1;
                is_signed <= sign;
            end else if (start_cnt) begin

                wire [8:0] sum_remainder = SR_reg[15:8] + (is_signed ? { {1{divisor_abs[7]}}, divisor_abs } : {1'b0, divisor_abs});
                if (sum_remainder[8]) begin
                    SR_reg <= {sum_remainder[7:0], SR_reg[7:0] << 1 | 1'b1};
                end else begin
                    SR_reg <= {sum_remainder[7:0], SR_reg[7:0] << 1};
                end
                cnt <= cnt + 1;
                if (cnt == 8) begin
                    start_cnt <= 0;
                end
            end
            if (!start_cnt && (cnt == 8)) begin

                reg [7:0] remainder = SR_reg[15:8];
                reg [7:0] quotient = SR_reg[7:0];
                if (is_signed) begin
                    remainder = original_dividend_sign ? -remainder : remainder;
                    quotient = (original_dividend_sign ^ original_divisor_sign) ? -quotient : quotient;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
                cnt <= 0;
            end
            if (!opn_valid) res_valid <= 0;
        end
    end

endmodule

