module fixed_point_subtractor #(
    parameter Q = 1,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    reg sign_a, sign_b;
    reg [N-1:0] a_abs, b_abs;
    reg sign_res;
    reg [N-1:0] sum;

    sign_a = a[N-1];
    sign_b = b[N-1];

    if (sign_a == sign_b) begin

        sum = a - b;
        sign_res = sign_a;
    end else begin

        a_abs = sign_a ? (~a + 1) : a;
        b_abs = sign_b ? (~b + 1) : b;

        if (a_abs > b_abs) begin
            sum = a_abs + b_abs;
            sign_res = 0;
        end else if (a_abs < b_abs) begin
            sum = a_abs + b_abs;
            sign_res = 1;
        end else begin
            sum = 0;
            sign_res = 0;
        end
    end


    if (sum == 0)
        sign_res = 0;


    c = {sign_res, sum[N-2:0]};
end

endmodule

