module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_mantissa2, b_mantissa2;
reg [47:0] product;
reg guard, round, sticky;
reg [7:0] exp_sum;
reg [9:0] final_exp;
reg [23:0] final_mantissa;
reg special_case;


function [5:0] leading_zeros;
    input [47:0] num;
    integer i;
    begin
        leading_zeros = 48;
        for (i = 47;
 i >= 0;
 i = i - 1) begin
            if (num[i]) begin
                leading_zeros = 47 - i;
                break;
            end
        end
    end
endfunction

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;

    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                if ((a_exponent == 8'hff && a_mantissa != 0) || 
                    (b_exponent == 8'hff && b_mantissa != 0)) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hff, 23'h000001};
                    counter <= 0;
                end

                else if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                    if ((a_exponent == 8'hff && b_exponent == 8'hff)) begin
                        if (a_mantissa == 0 && b_mantissa == 0) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                        end
                    end else begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end
                    counter <= 0;
                end

                else if ((a_exponent == 0 && a_mantissa == 0) || 
                         (b_exponent == 0 && b_mantissa == 0)) begin
                    z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    counter <= 0;
                end
                else begin

                    exp_sum <= a_exponent + b_exponent - 8'd127;
                    a_mantissa2 <= (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                    b_mantissa2 <= (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};
                    product <= a_mantissa2 * b_mantissa2;
                    counter <= 1;
                end
            end

            1: begin

                if (product[47:46] >= 2'b10) begin
                    product <= product >> 1;
                    exp_sum <= exp_sum + 1;
                end else if (product[47] == 0) begin

                    reg [5:0] shift = leading_zeros(product);
                    product <= product << shift;
                    exp_sum <= exp_sum - shift;
                end

                final_mantissa <= product[46:23];
                guard <= product[22];
                round <= product[21];
                sticky <= |product[20:0];
                counter <= 2;
            end

            2: begin

                reg round_up;
                if (guard) begin
                    if (round | sticky | final_mantissa[0]) round_up = 1;
                    else round_up = 0;
                end else begin
                    round_up = 0;
                end
                if (round_up) begin
                    final_mantissa <= final_mantissa + 1;
                    if (final_mantissa == 24'h1000000) begin
                        final_mantissa <= 24'h0;
                        final_exp <= exp_sum + 1;
                    end else begin
                        final_exp <= exp_sum;
                    end
                end else begin
                    final_exp <= exp_sum;
                end
                counter <= 3;
            end

            3: begin

                if (final_exp >= 8'hff) begin
                    z <= {z_sign, 8'hff, 23'h0};
                end else if (final_exp == 0) begin
                    z <= {z_sign, 8'h0, 23'h0};
                end else begin
                    z <= {z_sign, final_exp[7:0], final_mantissa[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

