module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);


    reg [$clog2(DEPTH):0] waddr_bin, raddr_bin;


    wire [$clog2(DEPTH):0] wptr, rptr;


    reg [$clog2(DEPTH):0] rptr_syn_1, rptr_syn;
    reg [$clog2(DEPTH):0] wptr_syn_1, wptr_syn;


    assign wptr = waddr_bin ^ (waddr_bin >> 1);
    assign rptr = raddr_bin ^ (raddr_bin >> 1);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
        end else if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
        end else if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_syn_1 <= 0;
            rptr_syn <= 0;
        end else begin
            rptr_syn_1 <= rptr;
            rptr_syn <= rptr_syn_1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_syn_1 <= 0;
            wptr_syn <= 0;
        end else begin
            wptr_syn_1 <= wptr;
            wptr_syn <= wptr_syn_1;
        end
    end


    assign wfull = (wptr == {~rptr_syn[$clog2(DEPTH)], ~rptr_syn[$clog2(DEPTH)-1], rptr_syn[$clog2(DEPTH)-2:0]});


    assign rempty = (rptr == wptr_syn);


    wire [$clog2(DEPTH)-1:0] waddr = waddr_bin[$clog2(DEPTH)-1:0];
    wire [$clog2(DEPTH)-1:0] raddr = raddr_bin[$clog2(DEPTH)-1:0];


    wire wen = winc && !wfull;
    wire ren = rinc && !rempty;


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram_inst (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(ren),
        .raddr(raddr),
        .rdata(rdata)
    );

endmodule


module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);


    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];


    always @(posedge wclk) begin
        if (wenc) begin
            RAM_MEM[waddr] <= wdata;
        end
    end


    always @(posedge rclk) begin
        if (renc) begin
            rdata <= RAM_MEM[raddr];
        end
    end

endmodule

