module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

localparam IDLE = 2'b00;
localparam RISE = 2'b01;
localparam FALL = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in) begin
                    state <= RISE;
                end
                data_out <= 0;
            end
            RISE: begin
                if (data_in) begin
                    state <= RISE;
                end else begin
                    state <= FALL;
                end
                data_out <= 0;
            end
            FALL: begin
                state <= IDLE;
                data_out <= 1;
            end
            default: begin
                state <= IDLE;
                data_out <= 0;
            end
        endcase
    end
end

endmodule

