code:
module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg carry_reg;
reg overflow_reg;

always @* begin
    case (aluc)
        ADD: begin
            {carry_reg, r} = a + b;
            overflow_reg = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry_reg, r} = a + b;
            overflow_reg = 1'b0;
        end
        SUB: begin
            {carry_reg, r} = a + (~b) + 1;
            overflow_reg = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry_reg, r} = a + (~b) + 1;
            overflow_reg = 1'b0;
        end
        AND: begin
            r = a & b;
            {carry_reg, overflow_reg} = 2'b0;
        end
        OR: begin
            r = a | b;
            {carry_reg, overflow_reg} = 2'b0;
        end
        XOR: begin
            r = a ^ b;
            {carry_reg, overflow_reg} = 2'b0;
        end
        NOR: begin
            r = ~(a | b);
            {carry_reg, overflow_reg} = 2'b0;
        end
        SLT: begin
            r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            {carry_reg, overflow_reg} = 2'b0;
        end
