module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg [7:0] NEG_DIVISOR;
reg [15:0] sr;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] quotient;
reg [7:0] remainder;
reg dividend_sign, divisor_sign, quotient_sign, remainder_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        quotient <= 0;
        remainder <= 0;
        sr <= 0;
        cnt <= 0;
        start_cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        NEG_DIVISOR <= 0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            dividend_sign <= sign ? dividend[7] : 1'b0;
            divisor_sign <= sign ? divisor[7] : 1'b0;
            quotient_sign <= (sign && (dividend[7] != divisor[7])) ? 1'b1 : 1'b0;
            remainder_sign <= sign ? dividend[7] : 1'b0;

            if (sign) begin
                dividend_abs <= dividend[7] ? -dividend : dividend;
                divisor_abs <= divisor[7] ? -divisor : divisor;
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
            end
            NEG_DIVISOR <= -divisor_abs;


            sr <= {8'b0, dividend_abs << 1};
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt <= 8) begin

                wire [8:0] sub_result = sr[15:8] - NEG_DIVISOR;
                wire borrow = sub_result[8];
                if (borrow) begin

                    sr[15:8] <= sr[15:8] + NEG_DIVISOR;

                    sr <= {sr[15:8] + NEG_DIVISOR, sr[7:0], 1'b0};
                end else begin

                    sr[15:8] <= sub_result[7:0];
                    sr <= {sub_result[7:0], sr[7:0], 1'b1};
                end
                cnt <= cnt + 1;
            end
            if (cnt == 8) begin
                start_cnt <= 0;

                quotient <= quotient_sign ? -sr[7:0] : sr[7:0];
                remainder <= remainder_sign ? -sr[15:8] : sr[15:8];
                res_valid <= 1;
            end
        end

        if (opn_valid && !res_valid) begin
            res_valid <= 0;
        end
    end
end


always @* begin
    result = {remainder, quotient};
end

endmodule

