module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        reg [8:0] remainder;
        reg [8:0] divisor_ext;
        integer i;

        remainder = 9'b0;
        divisor_ext = {1'b0, b_reg};

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = (remainder << 1) | a_reg[i];
            if (remainder >= divisor_ext) begin
                result[i] = 1'b1;
                remainder = remainder - divisor_ext;
            end else begin
                result[i] = 1'b0;
            end
        end

        odd = {7'b0, remainder};
    end

endmodule

