module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input C_in,
    output [4:1] S,
    output P,
    output G,
    output C_out
);
    wire [4:1] g, p, c;

    assign g = A & B;
    assign p = A ^ B;

    assign c[1] = g[1] | (p[1] & C_in);
    assign c[2] = g[2] | (p[2] & c[1]);
    assign c[3] = g[3] | (p[3] & c[2]);
    assign c[4] = g[4] | (p[4] & c[3]);

    assign S = p ^ c;

    assign G = g[4] | (p[4] & g[3]) | (p[4] & p[3] & g[2]) | (p[4] & p[3] & p[2] & g[1]);
    assign P = p[4] & p[3] & p[2] & p[1];
    assign C_out = G | (P & C_in);
