module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);

    always @(*) begin
        if (same_sign) begin
            res = a + b;
        end else begin
            wire [N-1:0] a_minus_b = a - b;
            wire [N-1:0] b_minus_a = b - a;

            if ($signed(a) > $signed(b)) begin
                res = a_minus_b;
            end else begin
                res = b_minus_a;
            end
        end
    end

    assign c = res;

endmodule

