module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] z_mantissa;
    reg [49:0] product;
    reg guard, round, sticky;
    reg [8:0] exponent_sum;
    reg [22:0] normalized_mantissa;
    reg [7:0] adjusted_exponent;
    reg overflow, underflow;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 1;
                end
                1: begin
                    if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 1'b1, 22'b0};
                        counter <= 0;
                    end else if ((a_exponent == 8'hff && !|a_mantissa) || (b_exponent == 8'hff && !|b_mantissa)) begin
                        if ((a_exponent == 8'hff && !|a_mantissa) && (b_exponent == 8'hff && !|b_mantissa)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'b0};
                        end else begin
                            z <= {1'b0, 8'hff, 1'b1, 22'b0};
                        end
                        counter <= 0;
                    end else if ((!|a_exponent && !|a_mantissa) || (!|b_exponent && !|b_mantissa)) begin
                        z <= {a_sign ^ b_sign, 1'b0, 23'b0};
                        counter <= 0;
                    end else begin
                        product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                        exponent_sum <= a_exponent + b_exponent - 127;
                        counter <= 2;
                    end
                end
                2: begin
                    if (product[47]) begin
                        normalized_mantissa <= product[46:23];
                        adjusted_exponent <= exponent_sum + 1;
                    end else begin
                        normalized_mantissa <= product[45:22];
                        adjusted_exponent <= exponent_sum;
                    end
                    guard <= (product[47]) ? product[22] : product[23];
                    round <= (product[47]) ? product[21] : product[22];
                    sticky <= (product[47]) ? |product[20:0] : |product[21:0];
                    counter <= 3;
                end
                3: begin
                    if (normalized_mantissa[23] && guard) begin
                        normalized_mantissa <= 24'h0;
                        adjusted_exponent <= adjusted_exponent + 1;
                    end
                    counter <= 4;
                end
                4: begin
                    if (guard && (round || sticky || normalized_mantissa[0])) begin
                        normalized_mantissa <= normalized_mantissa + 1;
                        if (normalized_mantissa + 1 == 24'h1000000) begin
                            normalized_mantissa <= 24'h0;
                            adjusted_exponent <= adjusted_exponent + 1;
                        end
                    end
                    counter <= 5;
                end
                5: begin
                    if (adjusted_exponent[8]) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (adjusted_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 1'b0, 23'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, adjusted_exponent[7:0], normalized_mantissa[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

endmodule

