            S3: next_state = IN ? S4 : S2;

            S4: next_state = IN ? S5 : S0;

            S5: next_state = S0;

            default: next_state = S0;

        endcase
    end


    always @(*) begin
        MATCH = (current_state == S5) & IN;
    end

