    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire wrstn,
    input wire winc,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire rrstn,
    input wire rinc,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);

localparam PTR_WIDTH = $clog2(DEPTH) + 1;


reg [PTR_WIDTH-1:0] waddr_bin;
wire [PTR_WIDTH-1:0] wptr_gray;


reg [PTR_WIDTH-1:0] raddr_bin;
wire [PTR_WIDTH-1:0] rptr_gray;


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync;
reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync;


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram_inst (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end

assign wptr_gray = (waddr_bin >> 1) ^ waddr_bin;


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end

assign rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync <= rptr_gray_sync1;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync <= wptr_gray_sync1;
    end
end


assign wfull = (wptr_gray == {~rptr_gray_sync[PTR_WIDTH-1:PTR_WIDTH-2], rptr_gray_sync[PTR_WIDTH-3:0]});
assign rempty = (rptr_gray == wptr_gray_sync);

endmodule

module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wire wclk,
    input wire wenc,
    input wire [$clog2(DEPTH)-1:0] waddr,
    input wire [WIDTH-1:0] wdata,
    input wire rclk,
    input wire renc,
    input wire [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule

