module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];


    integer i;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 3'd4;

            for (i = 0;
 i < 4;
 i = i + 1) 
                stack_mem[i] <= 4'b0;
            dataOut <= 4'b0;
        end
        else if (EN) begin
            if (!RW) begin 
                if (!FULL) begin
                    stack_mem[SP-1] <= dataIn;
                    SP <= SP - 1;
                end
            end
            else begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP-1];
                    stack_mem[SP-1] <= 4'b0;

                    SP <= SP + 1;
                end
            end
        end
    end


    always @(*) begin
        EMPTY = (SP == 3'd4);
        FULL = (SP == 3'd0);
    end

endmodule

