module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'b00;
        data_out <= 1'b0;
    end else begin
        state <= {state[0], data_in};
        data_out <= (state[1] == 1'b0) && (state[0] == 1'b1) && (data_in == 1'b0);
    end
end

