module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg quotient_sign;
reg remainder_sign;
reg [7:0] q;
reg [8:0] r;
reg [3:0] cnt;
reg start_cnt;
reg [16:0] SR;
reg [8:0] NEG_DIVISOR;

wire [8:0] shifted_r = {r[7:0], q[7]};
wire [7:0] new_q = {q[6:0], 1'b0};
wire [8:0] sub_result = shifted_r - NEG_DIVISOR;
wire carry_out = !sub_result[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        result <= 0;
        q <= 0;
        r <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
                quotient_sign <= dividend[7] ^ divisor[7];
                remainder_sign <= dividend[7];
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
                quotient_sign <= 0;
                remainder_sign <= 0;
            end

            SR <= {9'b0, abs_dividend, 1'b0} << 1;
            NEG_DIVISOR <= -{1'b0, (sign ? (divisor[7] ? -divisor : divisor) : divisor)};
            cnt <= 1;
            start_cnt <= 1;
        end else if (start_cnt) begin
            if (cnt == 8) begin

                if (quotient_sign) q <= -q;
                if (remainder_sign) r <= -r[7:0];
                result <= {r[7:0], q};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin
                if (carry_out) begin
                    r <= sub_result[7:0];
                    q <= new_q | 1;
                end else begin
                    r <= shifted_r[7:0];
                    q <= new_q;
                end
                SR <= {shifted_r[7:0], new_q};
                cnt <= cnt + 1;
            end
        end

        if (res_valid) begin
            res_valid <= 0;
        end
    end
end

endmodule

