module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] a_reg, b_reg;
reg [15:0] quotient;
reg [15:0] remainder;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    quotient = 0;
    remainder = {a_reg[15:8], 8'b0};
    for (int i = 0;
 i < 16;
 i++) begin
        remainder = remainder << 1;
        remainder[0] = a_reg[7 - i];
        if (remainder[15:8] >= b_reg) begin
            quotient = (quotient << 1) | 1'b1;
            remainder[15:8] = remainder[15:8] - b_reg;
        end else begin
            quotient = quotient << 1;
        end
    end
end

assign result = quotient;
assign odd = remainder;

endmodule

