module fixed_point_adder #(
    parameter Q = 3,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;
wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire [N-1:0] abs_a = a_sign ? (~a + 1) : a;
wire [N-1:0] abs_b = b_sign ? (~b + 1) : b;
wire abs_a_gt = (abs_a > abs_b);
wire abs_eq = (abs_a == abs_b);

always @* begin
    if (a_sign == b_sign) begin

        res = abs_a + abs_b;
        res[N-1] = a_sign;
    end else begin
        if (abs_a_gt) begin

            res = abs_a - abs_b;
            res[N-1] = a_sign;
        end else if (abs_b > abs_a) begin

            res = abs_b - abs_a;
            res[N-1] = b_sign;
        end else begin

            res = {N{1'b0}};
        end
    end
end

assign c = res;

endmodule

