module fixed_point_subtractor #(
    parameter Q = 3,
    parameter N = 4
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);

    always @(*) begin
        if (same_sign) begin
            res = a - b;
        end else begin
            if (a_sign) begin
                if (a <= b) begin
                    res = b - (~a + 1);
                    res[N-1] = 1;
                end else begin
                    res = a - b;
                    res[N-1] = 0;
                end
            end else begin
                if (a >= (~b + 1)) begin
                    res = a - (~b + 1);
                    res[N-1] = 0;
                end else begin
                    res = (~b + 1) - a;
                    res[N-1] = 1;
                end
            end
        end

        if (res == 0)
            res[N-1] = 0;

        c = res;
    end

endmodule

