module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [9:0] a_exponent, b_exponent, z_exponent;
reg [23:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg guard_bit, round_bit, sticky;
reg [47:0] product_shifted;
reg [22:0] mantissa_bits;
reg [23:0] rounded_mantissa;
reg exponent_overflow;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        a_sign <= 1'b0;
        b_sign <= 1'b0;
        z_sign <= 1'b0;
        a_exponent <= 9'b0;
        b_exponent <= 9'b0;
        z_exponent <= 9'b0;
        a_mantissa <= 24'b0;
        b_mantissa <= 24'b0;
        product <= 48'b0;
        guard_bit <= 1'b0;
        round_bit <= 1'b0;
        sticky <= 1'b0;
        product_shifted <= 48'b0;
        mantissa_bits <= 23'b0;
        rounded_mantissa <= 24'b0;
        exponent_overflow <= 1'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= {1'b0, a[30:23]};
                b_exponent <= {1'b0, b[30:23]};
                a_mantissa <= {1'b1, a[22:0]};
                b_mantissa <= {1'b1, b[22:0]};
                counter <= 3'b001;
            end
            3'b001: begin

                if ((a_exponent == 9'h0ff && a_mantissa != 0) || 
                    (b_exponent == 9'h0ff && b_mantissa != 0)) begin

                    z_sign <= a_sign ^ b_sign;
                    z_exponent <= 9'h0ff;
                    z_mantissa <= 23'h1;
                    counter <= 3'b010;
                end else if ((a_exponent == 9'h0ff && a_mantissa == 0) || 
                            (b_exponent == 9'h0ff && b_mantissa == 0)) begin

                    if (a_exponent == 9'h0ff && a_mantissa == 0 && 
                        b_exponent == 9'h0ff && b_mantissa == 0) begin

                        z_sign <= 1'b0;
                        z_exponent <= 9'h0ff;
                        z_mantissa <= 23'h1;
                    end else if (a_exponent == 9'h0ff && a_mantissa == 0) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'h0ff;
                        z_mantissa <= 0;
                    end else if (b_exponent == 9'h0ff && b_mantissa == 0) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 9'h0ff;
                        z_mantissa <= 0;
                    end else if (a_exponent == 0 && a_mantissa == 0 && 
                                b_exponent == 0 && b_mantissa == 0) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end else if (a_exponent == 0 && a_mantissa == 0) begin

                        z_sign <= b_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end else begin

                        z_sign <= a_sign;
                        z_exponent <= 0;
                        z_mantissa <= 0;
                    end
                    counter <= 3'b010;
                end else begin

                    product <= a_mantissa * b_mantissa;
                    z_exponent <= a_exponent + b_exponent - 9'd127;
                    counter <= 3'b010;
                end
            end
            3'b010: begin

                product_shifted <= product >> 1;
                mantissa_bits <= product_shifted[46:24];
                guard_bit <= product_shifted[23];
                round_bit <= product_shifted[22];
                sticky <= |product_shifted[21:0];
                counter <= 3'b011;
            end
            3'b011: begin

                exponent_overflow <= 1'b0;
                rounded_mantissa <= mantissa_bits;
                if (guard_bit) begin
                    if (round_bit || sticky) begin
                        rounded_mantissa <= mantissa_bits + 1;
                        exponent_overflow <= rounded_mantissa[23];
                    end else begin
                        if (mantissa_bits[0]) begin
                            rounded_mantissa <= mantissa_bits + 1;
                            exponent_overflow <= rounded_mantissa[23];
                        end
                    end
                end


                if (exponent_overflow) begin
                    if (z_exponent[8]) begin
                        z_exponent <= 9'h0ff;
                    end else begin
                        z_exponent <= z_exponent + 1;
                    end
                end else if (z_exponent[8]) begin
                    z_exponent <= 9'h0ff;
                end


                if (z_exponent[8] && (exponent_overflow == 1'b0)) begin
                    z_exponent <= 9'b0;
                    rounded_mantissa <= 24'b0;
                end

                counter <= 3'b100;
            end
            3'b100: begin

                z <= {z_sign, z_exponent[7:0], rounded_mantissa[22:0]};
                counter <= 3'b000;
            end
            default: counter <= 3'b000;
        endcase
    end
end

endmodule

