module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

parameter S0 = 3'd0,
          S1 = 3'd1,
          S2 = 3'd2,
          S3 = 3'd3,
          S4 = 3'd4;

reg [2:0] current_state, next_state;


always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin

    next_state = current_state;
    MATCH = 1'b0;

    case (current_state)
        S0: begin
            if (IN) begin
                next_state = S1;
            end else begin
                next_state = S0;
            end
            MATCH = 1'b0;
        end
        S1: begin
            if (IN) begin
                next_state = S1;
            end else begin
                next_state = S2;
            end
            MATCH = 1'b0;
        end
        S2: begin
            if (IN) begin
                next_state = S1;
            end else begin
                next_state = S3;
            end
            MATCH = 1'b0;
        end
        S3: begin
            if (IN) begin
                next_state = S4;
            } else begin
                next_state = S0;
            end
            MATCH = 1'b0;
        end
        S4: begin
            if (IN) begin
                next_state = S1;
                MATCH = 1'b1;
            } else begin
                next_state = S0;
            end
        end
        default: begin
            next_state = S0;
            MATCH = 1'b0;
        end
    endcase
end

