module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 8'd0) state <= s3_green;
            s3_green: if (cnt == 8'd0) state <= s2_yellow;
            s2_yellow: if (cnt == 8'd0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        case (state)
            s1_red: begin
                if (cnt == 8'd0) cnt <= 8'd60;
                else cnt <= cnt - 1;
            end
            s3_green: begin
                if (pass_request && (cnt > 8'd10)) cnt <= 8'd10;
                else if (cnt == 8'd0) cnt <= 8'd5;
                else cnt <= cnt - 1;
            end
            s2_yellow: begin
                if (cnt == 8'd0) cnt <= 8'd10;
                else cnt <= cnt - 1;
            end
            idle: cnt <= 8'd10;
            default: cnt <= cnt - 1;
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= (state == s1_red);
        p_yellow <= (state == s2_yellow);
        p_green <= (state == s3_green);
    end
end

assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;
assign clock = cnt;

endmodule

