reg [7:0] abs_divisor;
reg sign_dividend;
reg sign_divisor;
reg [7:0] quotient_reg;
reg [7:0] remainder_reg;
reg op_in_progress;

wire [8:0] temp_sub = {1'b0, SR[15:8]} + {1'b0, ~abs_divisor} + 1'b1;
wire carry_out = ~temp_sub[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
        abs_dividend <= 8'b0;
        abs_divisor <= 8'b0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        quotient_reg <= 8'b0;
        remainder_reg <= 8'b0;
        op_in_progress <= 0;
    end else begin
        if (opn_valid && !res_valid && !op_in_progress) begin
            sign_dividend <= sign ? dividend[7] : 1'b0;
            sign_divisor <= sign ? divisor[7] : 1'b0;
            if (sign) begin
                abs_dividend <= dividend[7] ? -dividend : dividend;
                abs_divisor <= divisor[7] ? -divisor : divisor;
            end else begin
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end
            SR <= {abs_dividend, 8'b0} << 1;
            cnt <= 4'd1;
            start_cnt <= 1'b1;
            op_in_progress <= 1'b1;
            res_valid <= 1'b0;
        end else if (op_in_progress) begin
            if (start_cnt) begin
                if (cnt == 4'd8) begin
                    start_cnt <= 1'b0;
                    cnt <= 4'd0;
                    if (sign) begin
                        remainder_reg <= sign_dividend ? -SR[15:8] : SR[15:8];
                        quotient_reg <= (sign_divisor ^ sign_dividend) ? -SR[7:0] : SR[7:0];
                    end else begin
                        remainder_reg <= SR[15:8];
                        quotient_reg <= SR[7:0];
                    end
                    result <= {remainder_reg, quotient_reg};
                    res_valid <= 1'b1;
                    op_in_progress <= 1'b0;
                end else begin
                    if (carry_out) begin
                        SR <= {temp_sub[7:0], SR[7:1], 1'b1};
                    end else begin
                        SR <= {SR[15:8], SR[7:1], 1'b0};
                    end
                    cnt <= cnt + 4'd1;
                end
            end
        end else begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

