module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input carry_in,
    output [16:1] S,
    output carry_out,
    output group_p,
    output group_g
);

wire [16:1] P, G;
wire [17:1] C;

assign C[0] = carry_in;

generate
    genvar i;
    for (i = 1;
 i <= 16;
 i = i + 1) begin : pg
        assign P[i] = A[i] ^ B[i];
        assign G[i] = A[i] & B[i];
        assign C[i] = G[i] | (P[i] & C[i-1]);
    end
endgenerate

function compute_group_g;
    input [16:1] P;
    input [16:1] G;
    integer j;
    begin
        compute_group_g = G[1];
        for (j = 2;
 j <= 16;
 j = j + 1)
            compute_group_g = compute_group_g | (&P[1:j-1] & G[j]);
    end
endfunction

assign group_g = compute_group_g(P, G);
assign group_p = &P;
assign carry_out = group_g | (group_p & carry_in);

generate
    for (i = 1;
 i <= 16;
 i = i + 1) begin : sum
        assign S[i] = P[i] ^ C[i-1];
    end
endgenerate

endmodule

