module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

    reg [1:0] count;
    reg [7:0] buffer [0:3];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 2'b00;
            valid_out <= 1'b0;
            data_out <= 10'b0;
            buffer[0] <= 8'b0;
            buffer[1] <= 8'b0;
            buffer[2] <= 8'b0;
            buffer[3] <= 8'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                buffer[count] <= data_in;
                case (count)
                    2'b00: count <= 2'b01;
                    2'b01: count <= 2'b10;
                    2'b10: count <= 2'b11;
                    2'b11: count <= 2'b00;
                endcase


                if (count == 2'b11) begin
                    data_out <= buffer[0] + buffer[1] + buffer[2] + data_in;
                    valid_out <= 1'b1;
                end
            end
        end
    end

endmodule

