module fixed_point_adder #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;

    if (a_sign == b_sign) begin

        res = a + b;
    end else begin

        if (a_abs > b_abs) begin
            res = {a_sign, a_abs - b_abs};
        end else begin
            res = {b_sign, b_abs - a_abs};
        end
    end


    c = res;
end

endmodule

