module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;

integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'd4;

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        EMPTY <= 1'b1;
        FULL <= 1'b0;
        dataOut <= 4'b0;
    end else if (EN) begin
        if (!FULL) begin 
            if (!EMPTY && RW == 1'b0) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end else if (RW == 1'b0) begin 
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end
        if (!EMPTY) begin 
            if (RW == 1'b1) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end

        EMPTY <= (SP == 3'd4);
        FULL <= (SP == 3'd0);
    end
end

endmodule

