module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 8'd3) state <= s3_green;
                s3_green: if (cnt == 8'd3) state <= s2_yellow;
                s2_yellow: if (cnt == 8'd3) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && green) begin
                cnt <= 8'd10;
            end else begin
                case (state)
                    s1_red: cnt <= cnt - 1;
                    s3_green: cnt <= cnt - 1;
                    s2_yellow: cnt <= cnt - 1;
                    default: cnt <= 8'd0;
                endcase

                if ((state == s1_red && cnt == 0) ||
                    (state == s3_green && cnt == 0) ||
                    (state == s2_yellow && cnt == 0)) begin
                    case (state)
                        s1_red: cnt <= 8'd10;
                        s3_green: cnt <= 8'd60;
                        s2_yellow: cnt <= 8'd5;
                        default: cnt <= 8'd0;
                    endcase
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {p_red, p_yellow, p_green} <= 3'b000;
        end else begin
            p_red <= (state == s1_red);
            p_yellow <= (state == s2_yellow);
            p_green <= (state == s3_green);
        end
    end

endmodule

