module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

localparam IDLE = 1'b0;
localparam BUSY = 1'b1;

reg state;
reg [7:0] divd_abs, divs_abs;
reg sign_q;
reg [7:0] neg_divs;
reg [16:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg neg_rem, quo_neg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 1'b0;
        result <= 16'b0;
        SR <= 17'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        sign_q <= 1'b0;
        divd_abs <= 8'b0;
        divs_abs <= 8'b0;
        neg_divs <= 8'b0;
        neg_rem <= 1'b0;
        quo_neg <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin
                    sign_q <= sign;
                    divd_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                    divs_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                    neg_divs <= ~divs_abs + 1'b1;
                    SR <= {divd_abs, 8'b0} << 1;
                    cnt <= 4'd1;
                    start_cnt <= 1'b1;
                    res_valid <= 1'b0;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (start_cnt) begin
                    if (cnt == 4'd8) begin
                        start_cnt <= 1'b0;
                        cnt <= 4'd0;
                        if (sign_q) begin
                            neg_rem <= dividend[7];
                            quo_neg <= (dividend[7] ^ divisor[7]);
                        end
                        result <= { (neg_rem ? -SR[16:9] : SR[16:9]), (quo_neg ? -SR[8:1] : SR[8:1]) };
                        res_valid <= 1'b1;
                        state <= IDLE;
                    end else begin
                        {SR, cnt} = ({SR[15:0] - neg_divs, SR[16]} >> 1) + (4'b1 << (15 - cnt));
                        cnt <= cnt + 4'd1;
                    end
                end
            end
        endcase
    end
end

endmodule

