module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] quotient = 16'b0;
        reg [15:0] remainder = {a_reg[15:8], 8'b0};
        reg [7:0] divisor = b_reg;
        integer i;

        for (i = 0;
 i < 16;
 i = i + 1) begin
            reg current_bit;
            if (i < 8)
                current_bit = a_reg[15 - i];
            else
                current_bit = a_reg[7 - (i - 8)];

            remainder = {remainder[14:0], current_bit};

            if (remainder >= {8'b0, divisor}) begin
                remainder = remainder - {8'b0, divisor};
                quotient = (quotient << 1) | 1'b1;
            end else begin
                quotient = (quotient << 1) | 1'b0;
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

