module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] mag_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] mag_b = sign_b ? (~b + 1) : b;

    wire same_sign = (sign_a == sign_b);
    wire [N-1:0] sum_mag = mag_a + mag_b;
    wire [N-1:0] sub_a_b = mag_a - mag_b;
    wire [N-1:0] sub_b_a = mag_b - mag_a;
    wire mag_a_gt_mag_b = (mag_a > mag_b);

    always @(*) begin
        if (same_sign) begin
            c = {sign_a, sum_mag};
        end else begin
            if (mag_a_gt_mag_b) begin
                c = {1'b0, sub_a_b};
            end else if (mag_b > mag_a) begin
                c = {1'b0, sub_b_a};
            end else begin
                c = {1'b0, {N-1{1'b0}}};
            end
        end
    end

endmodule

