module fixed_point_subtractor #(
    parameter Q,
    parameter N
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-2:0] a_mag = a[N-2:0];
    wire [N-2:0] b_mag = b[N-2:0];
    reg [N-1:0] sum;

    always @(*) begin
        if (a_sign == b_sign) begin

            res = a - b;
            if (res[N-1]) begin

                res = ~res + 1;
            end
        end else begin

            if (a_sign == 0 && b_sign == 1) begin

                sum = a_mag + b_mag;
                if (sum >= (1 << (N-1))) begin
                    res = {1'b1, (sum - (1 << (N-1)))};
                end else begin
                    res = {1'b0, sum};
                end
            end else begin

                sum = (~a_mag + 1) + b_mag;
                res = {1'b0, sum[N-2:0]};
            end
        end


        if (res[N-2:0] == 0) begin
            res[N-1] = 1'b0;
        end

        c = res;
    end

endmodule

