module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa, z_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 1;
                end
                1: begin 
                    if ((a_exponent == 8'hff && a_mantissa != 0) || (b_exponent == 8'hff && b_mantissa != 0)) begin

                        z <= {1'b0, 8'hff, 23'h1};
                    end else if ((a_exponent == 8'hff && a_mantissa == 0) || (b_exponent == 8'hff && b_mantissa == 0)) begin
                        if ((a_exponent == 8'hff && a_mantissa == 0) && (b_exponent == 8'hff && b_mantissa == 0)) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end
                    end else if (a_exponent == 0 && a_mantissa == 0) begin

                        z <= 0;
                    end else if (b_exponent == 0 && b_mantissa == 0) begin

                        z <= 0;
                    end else begin

                        reg [23:0] a_mantissa_ext = {1'b1, a_mantissa};
                        reg [23:0] b_mantissa_ext = {1'b1, b_mantissa};
                        product <= a_mantissa_ext * b_mantissa_ext;
                        counter <= 2;
                    end
                end
                2: begin 
                    if (product[47]) begin
                        z_mantissa <= product[46:24];
                        z_exponent <= a_exponent + b_exponent - 8'd126;
                    end else begin
                        z_mantissa <= product[45:23];
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    guard_bit <= product[23];
                    round_bit <= product[22];
                    sticky <= |product[21:0];
                    counter <= 3;
                end
                3: begin 

                    if (guard_bit & (round_bit | sticky)) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 24'hffffff) begin 
                            z_mantissa <= 24'h0;
                            z_exponent <= z_exponent + 1;
                        end
                    end
                    counter <= 4;
                end
                4: begin 
                    if (z_exponent >= 8'hfe) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (z_exponent == 0 && z_mantissa != 0) begin

                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end

endmodule

