module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);
    localparam PTR_WIDTH = $clog2(DEPTH) + 1;


    reg [PTR_WIDTH-1:0] wptr_bin;
    wire [PTR_WIDTH-1:0] wptr_gray;
    reg [PTR_WIDTH-1:0] wptr_gray_sync0, wptr_gray_sync1;


    reg [PTR_WIDTH-1:0] rptr_bin;
    wire [PTR_WIDTH-1:0] rptr_gray;
    reg [PTR_WIDTH-1:0] rptr_gray_sync0, rptr_gray_sync1;


    wire [$clog2(DEPTH)-1:0] waddr = wptr_bin[$clog2(DEPTH)-1:0];
    wire [$clog2(DEPTH)-1:0] raddr = rptr_bin[$clog2(DEPTH)-1:0];


    dual_port_RAM #(.WIDTH(WIDTH), .DEPTH(DEPTH)) ram_inst (
        .wclk(wclk),
        .wenc(winc & ~wfull),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc & ~rempty),
        .raddr(raddr),
        .rdata(rdata)
    );


    function [PTR_WIDTH-1:0] bin2gray;
        input [PTR_WIDTH-1:0] bin;
        bin2gray = bin ^ (bin >> 1);
    endfunction


    function [PTR_WIDTH-1:0] gray2bin;
        input [PTR_WIDTH-1:0] gray;
        reg [PTR_WIDTH-1:0] bin;
        integer i;
        begin
            bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2;
 i >=0;
 i=i-1)
                bin[i] = bin[i+1] ^ gray[i];
            gray2bin = bin;
        end
    endfunction


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) wptr_bin <= 0;
        else if (winc & ~wfull) wptr_bin <= wptr_bin + 1;
    end
    assign wptr_gray = bin2gray(wptr_bin);


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) rptr_bin <= 0;
        else if (rinc & ~rempty) rptr_bin <= rptr_bin + 1;
    end
    assign rptr_gray = bin2gray(rptr_bin);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) {wptr_gray_sync1, wptr_gray_sync0} <= 0;
        else {wptr_gray_sync1, wptr_gray_sync0} <= {rptr_gray_sync0, rptr_gray};
    end
    wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(wptr_gray_sync1);


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) {rptr_gray_sync1, rptr_gray_sync0} <= 0;
        else {rptr_gray_sync1, rptr_gray_sync0} <= {wptr_gray_sync0, wptr_gray};
    end
    wire [PTR_WIDTH-1:0] wptr_bin_sync = gray2bin(rptr_gray_sync1);


    assign wfull = (wptr_bin - rptr_bin_sync) >= DEPTH;
    assign rempty = (rptr_bin == wptr_bin_sync);
endmodule

