module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (Rst) begin

        SP <= 3'd4;
        EMPTY <= 1'b1;
        FULL <= 1'b0;
        dataOut <= 4'b0;
        stack_mem[0] <= 4'b0;
        stack_mem[1] <= 4'b0;
        stack_mem[2] <= 4'b0;
        stack_mem[3] <= 4'b0;
    end
    else if (EN) begin

        if (!FULL) begin
            if (!RW) begin
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end
        end

        if (!EMPTY) begin
            if (RW) begin
                dataOut <= stack_mem[SP];
                SP <= SP + 1;
            end
        end

        EMPTY <= (SP == 3'd4);
        FULL <= (SP == 3'd0);
    end
end

endmodule

