    parameter S0 = 2'd1;
    parameter S1 = 2'd2;
    parameter S2 = 2'd3;

    reg [1:0] state, next_state;


    always @(*) begin
        case (state)
            IDLE: next_state = data_in ? IDLE : S0;
            S0:   next_state = data_in ? S1 : IDLE;
            S1:   next_state = data_in ? S0 : S2;
            S2:   next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            state <= next_state;
            data_out <= (next_state == S2) ? 1'b1 : 1'b0;
        end
    end

endmodule

