module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'd0,
          s1_red = 2'd1,
          s2_yellow = 2'd2,
          s3_green = 2'd3;

reg [1:0] state, next_state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(*) begin
    case (state)
        idle: next_state = s1_red;
        s1_red: next_state = (cnt < 3) ? s3_green : s1_red;
        s3_green: next_state = (cnt < 3) ? s2_yellow : s3_green;
        s2_yellow: next_state = (cnt < 3) ? s1_red : s2_yellow;
        default: next_state = idle;
    endcase
end


always @(negedge rst_n or posedge clk) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            cnt <= 10;
        end else if (!green && p_green) begin
            cnt <= 60;
        end else if (!yellow && p_yellow) begin
            cnt <= 5;
        end else if (!red && p_red) begin
            cnt <= 10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
        red <= 0;
        yellow <= 0;
        green <= 0;
        state <= idle;
    end else begin
        state <= next_state;
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
        red <= (state == s1_red);
        yellow <= (state == s2_yellow);
        green <= (state == s3_green);
        clock <= cnt;
    end
end

