module edge_detect (
    input clk,
    input rst_n,
    input a,
    output rise,
    output down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        a_prev <= 1'b0;
    end else begin
        a_prev <= a;
    end
end

assign rise = (~rst_n) ? 1'b0 : (a_prev == 1'b0 && a == 1'b1);
assign down = (~rst_n) ? 1'b0 : (a_prev == 1'b1 && a == 1'b0);

endmodule

