    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg [7:0] data_lock;
    reg first_data_valid;
    reg [7:0] second_data;
    reg output_pending;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            valid_out <= 1'b0;
            data_lock <= 8'b0;
            first_data_valid <= 1'b0;
            second_data <= 8'b0;
            output_pending <= 1'b0;
        end else begin
            valid_out <= 1'b0;

            if (valid_in) begin
                if (!first_data_valid) begin
                    data_lock <= data_in;
                    first_data_valid <= 1'b1;
                end else begin
                    second_data <= data_in;
                    first_data_valid <= 1'b0;
                    output_pending <= 1'b1;
                end
            end

            if (output_pending) begin
                data_out <= {data_lock, second_data};
                valid_out <= 1'b1;
                output_pending <= 1'b0;
            end
        end
    end

endmodule

