module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] R, Q;
    reg [7:0] dividend_abs, divisor_abs;
    reg quotient_sign, remainder_sign;
    reg sign_reg;

    wire [7:0] NEG_DIVISOR = -divisor_abs;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 16'b0;
            cnt <= 0;
            start_cnt <= 0;
            R <= 8'b0;
            Q <= 8'b0;
            dividend_abs <= 8'b0;
            divisor_abs <= 8'b0;
            quotient_sign <= 0;
            remainder_sign <= 0;
            sign_reg <= 0;
        end else begin
            res_valid <= 0;
            if (opn_valid && !res_valid) begin
                sign_reg <= sign;
                if (sign) begin
                    quotient_sign <= dividend[7] ^ divisor[7];
                    remainder_sign <= dividend[7];
                    dividend_abs <= dividend[7] ? (-dividend) : dividend;
                    divisor_abs <= divisor[7] ? (-divisor) : divisor;
                end else begin
                    quotient_sign <= 0;
                    remainder_sign <= 0;
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                end
                R <= 8'b0;
                Q <= dividend_abs << 1;
                cnt <= 0;
                start_cnt <= 1;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    reg [7:0] R_shifted = {R[6:0], Q[7]};
                    reg [7:0] Q_shifted = {Q[6:0], 1'b0};
                    reg [7:0] sub_result = R_shifted - divisor_abs;
                    if (sub_result[7] == 0) begin
                        R <= sub_result;
                        Q_shifted[0] <= 1'b1;
                    end else begin
                        R <= R_shifted;
                        Q_shifted[0] <= 1'b0;
                    end
                    Q <= Q_shifted;
                    cnt <= cnt + 1;
                end else begin
                    start_cnt <= 0;
                    if (sign_reg) begin
                        if (quotient_sign) Q <= -Q;
                        if (remainder_sign) R <= -R;
                    end
                    result <= {R, Q};
                    res_valid <= 1;
                    cnt <= 0;
                end
            end
        end
    end

endmodule

