reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

reg [15:0] quo;
reg [8:0] rem;

always @(*) begin
    rem = {8'b0, a_reg[15:8]};
    quo = 16'b0;

    for (int i = 0;
 i < 16;
 i = i + 1) begin
        rem = {rem[7:0], a_reg[15 - i]};
        if (rem >= {1'b0, b_reg}) begin
            rem = rem - {1'b0, b_reg};
            quo[15 - i] = 1'b1;
        end else begin
            quo[15 - i] = 1'b0;
        end
    end

    odd = {rem[7:0], 8'b0};
    result = quo;
end

endmodule

