    if (!rst_n) begin
        sum_reg <= 10'd0;
        counter_reg <= 2'd0;
        valid_out <= 1'b0;
        data_out <= 10'd0;
    end else begin
        valid_out <= 1'b0;
        if (valid_in) begin
            if (counter_reg == 2'd3) begin
                sum_reg <= sum_reg + data_in;
                data_out <= sum_reg + data_in;
                valid_out <= 1'b1;
                counter_reg <= 2'd0;
            end else begin
                sum_reg <= sum_reg + data_in;
                counter_reg <= counter_reg + 1;
            end
        end
    end
end

endmodule

