module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
)(
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire [N-1:0] sum = a + b;
wire sum_overflow = (a_sign == b_sign) && (sum[N-1] != a_sign);


wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;
wire a_abs_gt_b_abs = a_abs > b_abs;
wire a_abs_lt_b_abs = a_abs < b_abs;

always @(*) begin
    if (a_sign == b_sign) begin
        if (sum_overflow) begin

            if (a_sign)
                res = {1'b1, {(N-Q-1){1'b0}}, {Q{1'b0}} };

            else
                res = {1'b0, {(N-Q-1){1'b1}}, {Q{1'b0}} };

        end else begin
            res = sum;
        end
    end else begin
        if (a_abs_gt_b_abs) begin
            res = a_abs - b_abs;
            res[N-1] = 0;

        end else if (a_abs_lt_b_abs) begin
            res = b_abs - a_abs;
            res[N-1] = 1;

        end else begin
            res = 0;
            res[N-1] = 0;

        end
    end
    c = res;
end

endmodule

