    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            z_mantissa <= 0;
            z_exponent <= 0;
            z <= 32'h0;
            a_reg <= 0;
            b_reg <= 0;
        end else begin
            case (counter)
                0: begin

                    a_reg <= a;
                    b_reg <= b;
                    a_sign <= a[31];
                    b_sign <= b[31];

                    if (a[30:23] == 8'hff) begin
                        a_exponent <= 8'hff;
                        a_mantissa <= a[22:0];
