                        b_exponent <= 8'hff;
                        b_mantissa <= b[22:0];
                    end else if (b[30:23] == 8'h00) begin
                        b_exponent <= 0;
                        b_mantissa <= {1'b0, b[22:0]};
                    end else begin
                        b_exponent <= b[30:23];
                        b_mantissa <= {1'b1, b[22:0]};
                    end
                    counter <= counter + 1;
                end
                1: begin

                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        counter <= 0;
                    end else if ((a_exponent == 8'hff && a_mantissa == 0) || 
                                (b_exponent == 8'hff && b_mantissa == 0)) begin
                        if ((a_exponent == 8'hff && a_mantissa == 0) && 
                            (b_exponent == 8'h00 || b_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                        counter <= 0;
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};

                        counter <= 0;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        counter <= counter + 1;
