module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg next_red, next_yellow, next_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case(state)
                idle: state <= s1_red;
                s1_red: if (cnt == 3) state <= s3_green;
                s2_yellow: if (cnt == 3) state <= s1_red;
                s3_green: if (cnt == 0) state <= s2_yellow;
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green) begin
                cnt <= (cnt > 10) ? 10 : cnt;
            end else if (!green && p_green) begin
                cnt <= 60;
            end else if (!yellow && p_yellow) begin
                cnt <= 5;
            end else if (!red && p_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    always @(*) begin
        case(state)
            idle: {next_red, next_yellow, next_green} = 3'b000;
            s1_red: {next_red, next_yellow, next_green} = 3'b100;
            s2_yellow: {next_red, next_yellow, next_green} = 3'b010;
            s3_green: {next_red, next_yellow, next_green} = 3'b001;
            default: {next_red, next_yellow, next_green} = 3'b000;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= next_red;
            p_yellow <= next_yellow;
            p_green <= next_green;
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

