module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg [7:0] data_lock;
    reg [7:0] data_second;
    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'b00;
            data_lock <= 8'b0;
            data_second <= 8'b0;
            valid_out <= 1'b0;
            data_out <= 16'b0;
        end else begin
            valid_out <= 1'b0;

            case (state)
                2'b00: begin 
                    if (valid_in) begin
                        data_lock <= data_in;
                        state <= 2'b01;
                    end
                end
                2'b01: begin 
                    if (valid_in) begin
                        data_second <= data_in;
                        state <= 2'b10;
                    end
                end
                2'b10: begin 
                    data_out <= {data_lock, data_second};
                    valid_out <= 1'b1;
                    state <= 2'b00;
                end
            endcase
        end
    end

