module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [8:0] rem;
    reg [7:0] divisor;
    reg [15:0] quotient;


    always @* begin
        a_reg = A;
        b_reg = B;
    end


    always @* begin
        rem = {1'b0, a_reg[15:8]};

        divisor = b_reg;
        quotient = 16'b0;

        for (int i = 0;
 i < 8;
 i++) begin

            reg bit;
            bit = a_reg[7 - i];


            reg [8:0] temp_rem;
            temp_rem = (rem << 1) | bit;


            if (temp_rem >= {1'b0, divisor}) begin
                quotient = (quotient << 1) | 1'b1;
                rem = temp_rem - {1'b0, divisor};
            end else begin
                quotient = quotient << 1;
                rem = temp_rem;
            end
        end


        result = {8'b0, quotient};
        odd = {8'b0, rem[7:0]};
    end

endmodule

