module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire eq_3, eq_2, eq_1, eq_0;
    wire gt_3, gt_2, gt_1, gt_0;
    wire lt_3, lt_2, lt_1, lt_0;


