    assign eq_2 = (A[2] == B[2]) & eq_3;
    assign eq_1 = (A[1] == B[1]) & eq_2;
    assign eq_0 = (A[0] == B[0]) & eq_1;


    assign gt_3 = A[3] & ~B[3];
    assign gt_2 = A[2] & ~B[2] & eq_3;
    assign gt_1 = A[1] & ~B[1] & eq_3 & eq_2;
    assign gt_0 = A[0] & ~B[0] & eq_3 & eq_2 & eq_1;


    assign lt_3 = ~A[3] & B[3];
    assign lt_2 = ~A[2] & B[2] & eq_3;
    assign lt_1 = ~A[1] & B[1] & eq_3 & eq_2;
    assign lt_0 = ~A[0] & B[0] & eq_3 & eq_2 & eq_1;


    assign A_greater = gt_3 | gt_2 | gt_1 | gt_0;
    assign A_less = lt_3 | lt_2 | lt_1 | lt_0;
    assign A_equal = eq_0;

