module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] sum_bin = A + B + Cin;
    wire [3:0] sum_initial = sum_bin[3:0];
    wire carry_initial = sum_bin[4];

    wire [3:0] sum_corrected = sum_initial + 4'd6;
    wire carry_correction = (sum_initial >= 4'd10) ? 1'b1 : 1'b0;

    assign Sum = (sum_initial >= 4'd10) ? sum_corrected : sum_initial;
    assign Cout = carry_initial || carry_correction;

endmodule

