module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    reg [N-1:0] res;
    reg [N-1:0] sum;

    always @(*) begin
        if (same_sign) begin
            res = a - b;
            res[N-1] = sign_a;
        end else begin
            if (sign_a == 0 && sign_b == 1) begin
                sum = abs_a + abs_b;
                if (abs_a > abs_b)
                    res = sum;
                else
                    res = ~sum + 1;
            end else begin
                sum = abs_a + abs_b;
                if (abs_a > abs_b)
                    res = ~sum + 1;
                else
                    res = sum;
            end
        end

        if (res == 0)
            res[N-1] = 1'b0;
    end

    assign c = res;

endmodule

