    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent_raw, b_exponent_raw;
    reg [22:0] a_mantissa_raw, b_mantissa_raw;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg z_sign;
    reg [7:0] z_exponent;
    reg [22:0] z_mantissa;
    reg guard, round, sticky;


    wire a_is_nan, b_is_nan, a_is_inf, b_is_inf, a_is_zero, b_is_zero;
    assign a_is_nan = (a_exponent_raw == 8'hff) && (a_mantissa_raw != 0);
    assign b_is_nan = (b_exponent_raw == 8'hff) && (b_mantissa_raw != 0);
    assign a_is_inf = (a_exponent_raw == 8'hff) && (a_mantissa_raw == 0);
    assign b_is_inf = (b_exponent_raw == 8'hff) && (b_mantissa_raw == 0);
    assign a_is_zero = (a_exponent_raw == 0) && (a_mantissa_raw == 0);
    assign b_is_zero = (b_exponent_raw == 0) && (b_mantissa_raw == 0);


    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b000;
            z <= 32'b0;
        end else begin
            case (counter)

                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent_raw <= a[30:23];
                    b_exponent_raw <= b[30:23];
                    a_mantissa_raw <= a[22:0];
                    b_mantissa_raw <= b[22:0];

                    if (a_is_nan || b_is_nan) begin
                        z <= {1'b0, 8'hff, 1'b1, 22'h0};

                        counter <= 3'b000;
                    end else if (a_is_inf && (b_is_zero || b_is_inf)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'h0};

                        counter <= 3'b000;
                    end else if (b_is_inf && (a_is_zero || a_is_inf)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'h0};

                        counter <= 3'b000;
                    end else if (a_is_inf || b_is_inf) begin
                        z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'h0};

                        counter <= 3'b000;
                    end else if (a_is_zero || b_is_zero) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};

                        counter <= 3'b000;
                    end else begin
                        counter <= 3'b001;
                    end
                end


                3'b001: begin

                    a_exponent <= (a_exponent_raw == 0) ? 8'd1 : a_exponent_raw;
                    a_mantissa <= (a_exponent_raw == 0) ? {1'b0, a_mantissa_raw} : {1'b1, a_mantissa_raw};


                    b_exponent <= (b_exponent_raw == 0) ? 8'd1 : b_exponent_raw;
                    b_mantissa <= (b_exponent_raw == 0) ? {1'b0, b_mantissa_raw} : {1'b1, b_mantissa_raw};

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end


                3'b010: begin

                    reg [5:0] leading_one;
                    leading_one = 0;
                    for (integer i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            leading_one = i;
                            i = -1;
                        end
                    end

                    if (product[47:46] >= 2'b10) begin 
                        z_exponent <= a_exponent + b_exponent - 8'd1;

                        product <= product >> 1;
                    end else if (leading_one < 46) begin
                        reg [4:0] shift_amount = 46 - leading_one;
                        z_exponent <= a_exponent + b_exponent - shift_amount - 8'd1;
                        product <= product << shift_amount;
                    end else begin
                        z_exponent <= a_exponent + b_exponent;
                    end

                    counter <= 3'b011;
                end


                3'b011: begin
                    guard <= product[0];
                    round <= product[1];
                    sticky <= |product[47:2];

                    if (guard && (round || sticky || !product[0])) begin
                        product <= product + 1;
                        if (product[47]) begin
                            product <= product >> 1;
                            z_exponent <= z_exponent + 1;
                        end
                    end

                    z_mantissa <= product[46:24];
                    counter <= 3'b100;
                end


                3'b100: begin
                    if (z_exponent > 8'd254) begin 
                        z <= {z_sign, 8'hff, 1'b0, 22'h0};
                    end else if (z_exponent == 8'd0) begin 
                        z <= {z_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

