module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    parameter idle     = 2'b00;
    parameter s1_red   = 2'b01;
    parameter s2_yellow= 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
            cnt <= 10;
        end else begin

            case (state)
                idle: begin
                    state <= s1_red;
                end
                s1_red: begin
                    p_red <= 1;
                    if (cnt == 0) begin
                        state <= s3_green;
                    end
                end
                s3_green: begin
                    p_green <= 1;
                    if (pass_request && green) begin
                        cnt <= 10;
                    end else if (cnt == 0) begin
                        state <= s2_yellow;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    p_yellow <= 1;
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase


            if (state != s3_green && p_green) begin
                cnt <= 60;
                p_green <= 0;
            end else if (state != s2_yellow && p_yellow) begin
                cnt <= 5;
                p_yellow <= 0;
            end else if (state != s1_red && p_red) begin
                cnt <= 10;
                p_red <= 0;
            end
        end
    end

endmodule

