module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);

    parameter ADD   = 6'b100000;
    parameter ADDU  = 6'b100001;
    parameter SUB   = 6'b100010;
    parameter SUBU  = 6'b100011;
    parameter AND   = 6'b100100;
    parameter OR    = 6'b100101;
    parameter XOR   = 6'b100110;
    parameter NOR   = 6'b100111;
    parameter SLT   = 6'b101010;
    parameter SLTU  = 6'b101011;
    parameter SLL   = 6'b000000;
    parameter SRL   = 6'b000010;
    parameter SRA   = 6'b000011;
    parameter SLLV  = 6'b000100;
    parameter SRLV  = 6'b000110;
    parameter SRAV  = 6'b000111;
    parameter LUI   = 6'b001111;

    reg a_lt_b;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? a_lt_b : 1'bz;

    always @(*) begin

        r = 32'b0;
        carry = 1'b0;
        overflow = 1'b0;
        case (aluc)
            ADD: begin
                {carry, r} = {a + b};
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                r = a + b;
                carry = (a + b) >> 32;
            end
            SUB: begin
                {carry, r} = {a - b};
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                r = a - b;
                carry = (a >= b) ? 1'b1 : 1'b0;
            end
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: begin
                a_lt_b = ($signed(a) < $signed(b));
                r = {31'b0, a_lt_b};
            end
            SLTU: begin
                a_lt_b = (a < b);
                r = {31'b0, a_lt_b};
            end
            SLL: r = b << a[4:0];
            SRL: r = b >> a[4:0];
            SRA: r = $signed(b) >>> a[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = $signed(b) >>> a[4:0];
            LUI: r = {a[15:0], 16'b0};
            default: begin
                r = 32'bz;
                carry = 1'bz;
                overflow = 1'bz;
            end
        endcase
    end
endmodule

