module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam PROCESSING = 2'b01;

    reg [7:0] abs_dividend, abs_divisor;
    reg sign_dividend, sign_divisor;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            SR <= 0;
            cnt <= 0;
            NEG_DIVISOR <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            sign_dividend <= dividend[7];
                            sign_divisor <= divisor[7];
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                        end else begin
                            sign_dividend <= 0;
                            sign_divisor <= 0;
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                        end


                        SR <= {abs_dividend, 1'b0};

                        NEG_DIVISOR <= -abs_divisor;

                        cnt <= 1;
                        state <= PROCESSING;
                        res_valid <= 0;
                    end
                end
                PROCESSING: begin
                    if (cnt < 8) begin

                        if ($signed(SR[16:8]) + $signed(NEG_DIVISOR) >= 0) begin

                            SR[16:8] <= $signed(SR[16:8]) + $signed(NEG_DIVISOR);
                            SR[0] <= 1;
                        end else begin
                            SR[0] <= 0;
                        end

                        SR <= SR << 1;
                        cnt <= cnt + 1;
                    end else begin

                        if ($signed(SR[16:8]) + $signed(NEG_DIVISOR) >= 0) begin
                            SR[16:8] <= $signed(SR[16:8]) + $signed(NEG_DIVISOR);
                            SR[0] <= 1;
                        end else begin
                            SR[0] <= 0;
                        end
                        SR <= SR << 1;

                        reg [7:0] rem, quo;
                        rem = SR[16:9];
                        quo = SR[7:0];

                        if (sign) begin
                            rem = sign_dividend ? -rem : rem;
                            quo = (sign_dividend ^ sign_divisor) ? -quo : quo;
                        end
                        result <= {rem, quo};
                        res_valid <= 1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

