module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            reg [N-1:0] abs_a, abs_b, sum_abs;
            abs_a = a[N-1] ? (~a + 1) : a;
            abs_b = b[N-1] ? (~b + 1) : b;
            sum_abs = abs_a + abs_b;
            res = {sum_abs[N-1], sum_abs[N-2:0]};
        end else begin

            reg [N-1:0] abs_a, abs_b, diff;
            abs_a = a[N-1] ? (~a + 1) : a;
            abs_b = b[N-1] ? (~b + 1) : b;
            if (abs_a > abs_b) begin
                diff = abs_a - abs_b;
                res = {a[N-1], diff[N-2:0]};
            end else if (abs_b > abs_a) begin
                diff = abs_b - abs_a;
                res = {b[N-1], diff[N-2:0]};
            end else begin
                res = {1'b0, {(N-2){1'b0}}};
            end
        end
        c = res;
    end

endmodule

