module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);
    wire diff_sign = !same_sign;

    always @(*) begin
        if (same_sign) begin

            reg [N-1:0] temp = a - b;
            if (temp[N-1] != sign_a) 
                res = -temp;
            else
                res = temp;
        end else begin

            reg [N-1:0] abs_a, abs_b, larger, smaller;
            reg sign_result;

            abs_a = sign_a ? -a : a;
            abs_b = sign_b ? -b : b;

            if (abs_a > abs_b) begin
                larger = abs_a;
                smaller = abs_b;
                sign_result = sign_a;
            end else begin
                larger = abs_b;
                smaller = abs_a;
                sign_result = sign_b;
            end

            res = larger - smaller;
            res[N-1] = sign_result;
        end
    end

    assign c = res;

endmodule

