module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input  wire              wclk,
    input  wire              rclk,
    input  wire              wrstn,
    input  wire              rrstn,
    input  wire              winc,
    input  wire              rinc,
    input  wire [WIDTH-1:0] wdata,
    output reg               wfull,
    output reg               rempty,
    output reg [WIDTH-1:0]  rdata
);

localparam WADDR = $clog2(DEPTH);
localparam PTR_WIDTH = WADDR + 1;

reg [PTR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [PTR_WIDTH-1:0] wptr_gray, rptr_gray;

reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync;
reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync;


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[WADDR-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[WADDR-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
        wptr_gray <= bin2gray(waddr_bin + 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr_gray <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
        rptr_gray <= bin2gray(raddr_bin + 1);
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync  <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync  <= wptr_gray_sync1;
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync  <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync  <= rptr_gray_sync1;
    end
end


wire [PTR_WIDTH-1:0] rptr_bin_sync, wptr_bin_sync;
assign rptr_bin_sync = gray2bin(rptr_gray_sync);
assign wptr_bin_sync = gray2bin(wptr_gray_sync);


always @(*) begin
    wfull = (waddr_bin - rptr_bin_sync) >= DEPTH;
    rempty = (raddr_bin == wptr_bin_sync);
end


function [PTR_WIDTH-1:0] gray2bin;
    input [PTR_WIDTH-1:0] gray;
    integer i;
    reg [PTR_WIDTH-1:0] bin;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction


function [PTR_WIDTH-1:0] bin2gray;
    input [PTR_WIDTH-1:0] bin;
    bin2gray = bin ^ (bin >> 1);
endfunction

endmodule

