    if (!rst_n) begin
        cnt <= 2'b00;
        data <= 4'b0;
        valid_out <= 1'b0;
        dout <= 1'b0;
    end else begin
        if (cnt == 2'b11) begin

            data <= d;
            cnt <= 2'b00;
            valid_out <= 1'b1;
