module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output reg flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] res;
    reg carry_out, overflow_out;

    assign zero    = (res == 32'b0);
    assign negative= res[31];
    assign carry   = carry_out;
    assign overflow= overflow_out;

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry_out, res} = {1'b0, a} + {1'b0, b};
                overflow_out = (a[31] == b[31]) && (res[31] != a[31]);
                flag = 1'b0;
            end
            ADDU: begin
                {carry_out, res} = {1'b0, a} + {1'b0, b};
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SUB: begin
                {carry_out, res} = {1'b0, a} - {1'b0, b};
                overflow_out = (a[31] != b[31]) && (res[31] != a[31]);
                flag = 1'b0;
            end
            SUBU: begin
                {carry_out, res} = {1'b0, a} - {1'b0, b};
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            AND: begin
                res = a & b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            OR: begin
                res = a | b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            XOR: begin
                res = a ^ b;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            NOR: begin
                res = ~(a | b);
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = ($signed(a) < $signed(b));
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = (a < b);
            end
            SLL: begin
                res = a << b[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SRL: begin
                res = a >> b[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SRA: begin
                res = $signed(a) >>> b[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SLLV: begin
                res = a << a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SRLV: begin
                res = a >> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            SRAV: begin
                res = $signed(a) >>> a[4:0];
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            LUI: begin
                res = {b[15:0], 16'b0};
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
            default: begin
                res = 32'bz;
                carry_out = 1'b0;
                overflow_out = 1'b0;
                flag = 1'b0;
            end
        endcase
        r = res;
    end

endmodule

