module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg sign_quotient, sign_remainder;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [1:0] state;

localparam IDLE = 2'b00;
localparam BUSY = 2'b01;
localparam DONE = 2'b10;

wire [8:0] NEG_DIVISOR;
wire [16:0] subtract_result;
wire carry_out;


wire [7:0] abs_dividend = (dividend[7] && sign) ? (~dividend + 1) : dividend;
wire [7:0] abs_divisor = (divisor[7] && sign) ? (~divisor + 1) : divisor;

assign NEG_DIVISOR = {1'b0, abs_divisor};


always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 16'h0000;
        SR <= 16'h0000;
        cnt <= 0;
        start_cnt <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        sign_quotient <= 0;
        sign_remainder <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin
                    sign_quotient <= (sign) ? (dividend[7] ^ divisor[7]) : 0;
                    sign_remainder <= (sign) ? dividend[7] : 0;
                    dividend_abs <= abs_dividend;
                    divisor_abs <= abs_divisor;
                    SR <= {8'b0, (abs_dividend << 1)};
                    cnt <= 1;
                    start_cnt <= 1;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (start_cnt) begin
                    if (cnt == 8) begin
                        start_cnt <= 0;
                        cnt <= 0;

                        result[15:8] <= (sign && sign_remainder) ? (-SR[15:8]) : SR[15:8];
                        result[7:0] <= (sign && sign_quotient) ? (-SR[7:0]) : SR[7:0];
                        state <= DONE;
                    end else begin
                        subtract_result = {1'b0, SR[15:8]} + NEG_DIVISOR;
                        carry_out = subtract_result[16];
                        if (carry_out) begin
                            SR <= {subtract_result[15:8], SR[7:1], 1'b1};
                        end else begin
                            SR <= {SR[15:8], SR[7:1], 1'b0};
                        end
                        cnt <= cnt + 1;
                    end
                end
            end
            DONE: begin
                res_valid <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

