module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

wire [3:0] difference;
wire [3:0] borrow;

assign borrow[0] = (~A[0] & B[0]) | ((~A[0] | B[0]) & 1'b0);
assign difference[0] = A[0] ^ B[0] ^ 1'b0;

assign borrow[1] = (~A[1] & B[1]) | ((~A[1] | B[1]) & borrow[0]);
assign difference[1] = A[1] ^ B[1] ^ borrow[0];

assign borrow[2] = (~A[2] & B[2]) | ((~A[2] | B[2]) & borrow[1]);
assign difference[2] = A[2] ^ B[2] ^ borrow[1];

assign borrow[3] = (~A[3] & B[3]) | ((~A[3] | B[3]) & borrow[2]);
assign difference[3] = A[3] ^ B[3] ^ borrow[2];

wire no_borrow = ~borrow[3];
wire all_zero = (difference[0] == 0) && (difference[1] == 0) && (difference[2] == 0) && (difference[3] == 0);

assign A_less = borrow[3];
assign A_greater = no_borrow && !all_zero;
assign A_equal = no_borrow && all_zero;

endmodule

