module fixed_point_adder #(
    parameter Q = 1,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-2:0] a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

    if (a_sign == b_sign) begin
        res = a + b;
    end else begin
        if (a_mag > b_mag) begin
            res[N-1] = a_sign;
            res[N-2:0] = a_mag - b_mag;
        end else if (a_mag < b_mag) begin
            res[N-1] = b_sign;
            res[N-2:0] = b_mag - a_mag;
        end else begin
            res = 0;
        end
    end
end

assign c = res;

endmodule

