module fixed_point_subtractor #(
    parameter Q = 2,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
reg sign_res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        res = a - b;
        sign_res = a[N-1];
    end else begin

        if (a >= b) begin
            res = a - b;
            sign_res = 0;
        end else begin
            res = b - a;
            sign_res = 1;
        end
    end


    if (res == 0)
        sign_res = 1'b0;
end

assign c = {sign_res, res[N-1:0]};

endmodule

