module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [22:0] z_mantissa;
reg [49:0] product;
reg [47:0] normalized_product;
reg guard_bit, round_bit, sticky;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
    end else begin
        case (counter)
            3'b0: begin
                a_sign <= a[31];
                a_exponent <= a[30:23];
                a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_sign <= b[31];
                b_exponent <= b[30:23];
                b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= 3'b1;
            end

            3'b1: begin

                if ((a_exponent == 8'hFF && a_mantissa != 0) || 
                    (b_exponent == 8'hFF && b_mantissa != 0)) begin
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                    counter <= 3'b7;
                end else if ((a_exponent == 8'hFF && a_mantissa == 0) || 
                            (b_exponent == 8'hFF && b_mantissa == 0)) begin
                    if ((a_exponent == 8'hFF && a_mantissa == 0) && 
                        (b_exponent == 8'hFF && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                    end else begin
                        if ((a_exponent == 8'hFF && a_mantissa == 0) && 
                            (b_exponent == 8'h00 && b_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                        end else if ((b_exponent == 8'hFF && b_mantissa == 0) && 
                                   (a_exponent == 8'h00 && a_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                        end
                    end
                    counter <= 3'b7;
                end else if ((a_exponent == 8'h00 && a_mantissa == 0) || 
                            (b_exponent == 8'h00 && b_mantissa == 0)) begin
                    if ((a_exponent == 8'h00 && a_mantissa == 0) && 
                        (b_exponent == 8'h00 && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};
                    end
                    counter <= 3'b7;
                end else begin
                    product <= {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    counter <= 3'b2;
                end
            end

            3'b2: begin

                integer i;
                reg [47:0] temp_product;
                temp_product = product;
                for (i=47;
 i>=0;
 i=i-1) begin
                    if (temp_product[i]) begin
                        if (i == 47) begin
                            normalized_product <= product >> 1;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            normalized_product <= product << (47 - i);
                            z_exponent <= z_exponent - (47 - i);
                        end
                        break;
                    end
                end
                counter <= 3'b3;
            end

            3'b3: begin

                guard_bit <= normalized_product[45];
                round_bit <= normalized_product[44];
                sticky <= |normalized_product[43:0];
                reg [23:0] mantissa_temp;
                mantissa_temp = {1'b0, normalized_product[46:24]};
                if (guard_bit && (round_bit || sticky)) begin
                    mantissa_temp = mantissa_temp + 1;
                end
                if (mantissa_temp[23]) begin
                    z_exponent <= z_exponent + 1;
                    mantissa_temp = {1'b0, mantissa_temp[23:1]};
                end
                z_mantissa <= mantissa_temp[22:0];
                if (z_exponent >= 8'hFF) begin
                    z <= {z_sign, 8'hFF, 23'h0};
                end else if (z_exponent == 0) begin
                    z <= {z_sign, 8'h0, z_mantissa};
                end else begin
                    z <= {z_sign, z_exponent, z_mantissa};
                end
                counter <= 3'b7;
            end

            default: counter <= 3'b0;
        endcase
    end
end

endmodule

