module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

assign result = A - B;

assign overflow = ( ( (A[63] == 1'b0) & (B[63] == 1'b1) & (result[63] == 1'b1) ) |
                   ( (A[63] == 1'b1) & (B[63] == 1'b0) & (result[63] == 1'b0) ) ) ? 1'b1 : 1'b0;

