module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state, next_state;

localparam IDLE = 2'b00,
           S0   = 2'b01,
           S1   = 2'b10,
           S2   = 2'b11;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end
    else begin
        state <= next_state;
        case (state)
            IDLE: next_state <= (data_in) ? IDLE : S0;
            S0:   next_state <= (data_in) ? S1 : S0;
            S1:   next_state <= (data_in) ? S0 : S2;
            S2:   next_state <= IDLE;
            default: next_state <= IDLE;
        endcase

        data_out <= (state == S2) ? 1'b1 : 1'b0;
    end
end

endmodule

