module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 0,
          s1_red = 1,
          s2_yellow = 2,
          s3_green = 3;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s3_green: if (cnt == 0) state <= s2_yellow;
            s2_yellow: if (cnt == 0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && green) cnt <= 8'd10;
        else if (!green && p_green) cnt <= 8'd60;
        else if (!yellow && p_yellow) cnt <= 8'd5;
        else if (!red && p_red) cnt <= 8'd10;
        else cnt <= cnt - 1;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end


assign {red, yellow, green} = 
    (state == idle) ? 3'b000 :
    (state == s1_red) ? 3'b100 :
    (state == s3_green) ? 3'b001 :
    (state == s2_yellow) ? 3'b010 : 3'b000;

assign clock = cnt;

endmodule

