module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);
    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg [32:0] add_sum, sub_diff;
    wire [32:0] add_u, sub_u;

    always @(*) begin
        res = 32'd0;
        carry = 1'b0;
        overflow = 1'b0;

        case (aluc)
            ADD: begin
                add_sum = {1'b0, a} + {1'b0, b};
                res = add_sum[31:0];
                carry = add_sum[32];
                overflow = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                add_sum = {1'b0, a} + {1'b0, b};
                res = add_sum[31:0];
                carry = add_sum[32];
            end
            SUB: begin
                sub_diff = {1'b0, a} - {1'b0, b};
                res = sub_diff[31:0];
                carry = sub_diff[32];
                overflow = (a[31] != b[31]) && (res[31] != a[31]);
            end
            SUBU: begin
                sub_diff = {1'b0, a} - {1'b0, b};
                res = sub_diff[31:0];
                carry = sub_diff[32];
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            SLTU: res = (a < b) ? 32'd1 : 32'd0;
            SLL: res = b << a[4:0];
            SRL: res = b >> a[4:0];
            SRA: res = $signed(b) >>> a[4:0];
            SLLV: res = a << a[4:0];
            SRLV: res = a >> a[4:0];
            SRAV: res = $signed(a) >>> a[4:0];
            LUI: res = {a[15:0], 16'b0};
            default: res = 32'bz;
        endcase
    end

    assign r = res;
    assign zero = (res == 32'd0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

