module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg sign_dividend;
    reg sign_divisor;
    reg sign_quotient;
    reg sign_remainder;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;


    localparam IDLE = 0;
    localparam PROCESSING = 1;
    reg state;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        state <= PROCESSING;
                        res_valid <= 0;

                        sign_dividend <= dividend[7];
                        sign_divisor <= divisor[7];
                        sign_quotient <= (sign) ? (dividend[7] ^ divisor[7]) : 0;
                        sign_remainder <= dividend[7];

                        dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;



                        SR <= {dividend_abs, 8'b0} << 1;
                        cnt <= 1;
                        start_cnt <= 1;
                    end
                end
                PROCESSING: begin
                    if (start_cnt) begin
                        start_cnt <= 0;
                        cnt <= 1;
                    end
                    if (cnt < 8) begin

                        SR <= SR << 1;

                        if (SR[15:8] >= divisor_abs) begin
                            SR[15:8] <= SR[15:8] - divisor_abs;
                            SR[7] <= 1'b1;
                        end else begin
                            SR[7] <= 1'b0;
                        end
                        cnt <= cnt + 1;
                    end else begin

                        state <= IDLE;
                        res_valid <= 1;

                        reg [7:0] remainder_abs = SR[15:8];
                        reg [7:0] quotient_abs = SR[7:0];
                        reg [7:0] remainder, quotient;
                        if (sign) begin
                            remainder = sign_remainder ? -{1'b0, remainder_abs} : {1'b0, remainder_abs};
                            quotient = sign_quotient ? -{1'b0, quotient_abs} : {1'b0, quotient_abs};
                        end else begin
                            remainder = {1'b0, remainder_abs};
                            quotient = {1'b0, quotient_abs};
                        end
                        result <= {remainder, quotient};
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

