module cla_4bit (
    input [4:1] A,
    input [4:1] B,
    input Cin,
    output [4:1] S,
    output P,
    output G,
    output Cout
);
    wire [4:1] P_i = A ^ B;
    wire [4:1] G_i = A & B;

    wire C1, C2, C3, C4;

    assign C1 = P_i[1] & Cin;
    assign C2 = G_i[2] | (P_i[2] & G_i[1]) | (P_i[2] & P_i[1] & Cin);
    assign C3 = G_i[3] | (P_i[3] & G_i[2]) | (P_i[3] & P_i[2] & G_i[1]) | (P_i[3] & P_i[2] & P_i[1] & Cin);
    assign C4 = G_i[4] | (P_i[4] & G_i[3]) | (P_i[4] & P_i[3] & G_i[2]) | (P_i[4] & P_i[3] & P_i[2] & G_i[1]) | (P_i[4] & P_i[3] & P_i[2] & P_i[1] & Cin);

    assign S[1] = P_i[1] ^ Cin;
    assign S[2] = P_i[2] ^ C1;
    assign S[3] = P_i[3] ^ C2;
    assign S[4] = P_i[4] ^ C3;

