module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    if (a[N-1] == b[N-1]) begin
        res = a + b;
    end else begin
        reg [N-1:0] abs_a = a[N-1] ? (~a + 1) : a;
        reg [N-1:0] abs_b = b[N-1] ? (~b + 1) : b;

        if (abs_a > abs_b) begin
            res = {a[N-1], abs_a - abs_b};
        end else if (abs_b > abs_a) begin
            res = {b[N-1], abs_b - abs_a};
        end else begin
            res = {1'b0, {(N-1){1'b0}}};
        end
    end
    c = res;
end

endmodule

