module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg a_is_nan, a_is_inf, a_is_zero;
    reg b_is_nan, b_is_inf, b_is_zero;
    reg [23:0] a_mantissa_ext, b_mantissa_ext;
    reg [47:0] product;
    reg [9:0] exponent_sum;
    reg product_ge_2;
    reg [22:0] mantissa_frac;
    reg guard_bit, round_bit, sticky;
    reg round_up;
    reg [23:0] new_mantissa;
    reg z_sign;
    reg [9:0] z_exponent;
    reg [22:0] z_mantissa;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            a_is_nan <= 0;
            a_is_inf <= 0;
            a_is_zero <= 0;
            b_is_nan <= 0;
            b_is_inf <= 0;
            b_is_zero <= 0;
            product <= 0;
            exponent_sum <= 0;
            product_ge_2 <= 0;
            mantissa_frac <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            round_up <= 0;
            new_mantissa <= 0;
            z_sign <= 0;
            z_exponent <= 0;
            z_mantissa <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    a_is_nan <= (a[30:23] == 8'hFF) && (a[22:0] != 0);
                    a_is_inf <= (a[30:23] == 8'hFF) && (a[22:0] == 0);
                    a_is_zero <= (a[30:23] == 0) && (a[22:0] == 0);

                    b_is_nan <= (b[30:23] == 8'hFF) && (b[22:0] != 0);
                    b_is_inf <= (b[30:23] == 8'hFF) && (b[22:0] == 0);
                    b_is_zero <= (b[30:23] == 0) && (b[22:0] == 0);


                    a_mantissa_ext <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa_ext <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if (a_is_nan || b_is_nan) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 1'b1, 22'h000001};
                        counter <= 3'b001;
                    end else if ((a_is_inf && b_is_zero) || (b_is_inf && a_is_zero)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                        counter <= 3'b001;
                    end else if (a_is_inf || b_is_inf) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                        counter <= 3'b001;
                    end else if (a_is_zero || b_is_zero) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h000000};
                        counter <= 3'b001;
                    end else begin

                        exponent_sum <= {1'b0, a_exponent} + {1'b0, b_exponent} - 9'h000C2;
                        product <= a_mantissa_ext * b_mantissa_ext;
                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    product_ge_2 <= product[47:46] >= 2'b10;
                    if (product_ge_2) begin
                        mantissa_frac <= product[46:24];
                        exponent_sum <= exponent_sum + 1;
                    end else begin
                        mantissa_frac <= product[45:23];
                    end
                    counter <= 3'b010;
                end

                3'b010: begin

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    round_up <= (guard_bit && (round_bit || sticky)) || (guard_bit && !round_bit && !sticky);
                    new_mantissa <= {1'b0, mantissa_frac} + round_up;
                    if (new_mantissa[23]) begin
                        z_mantissa <= new_mantissa[22:0];
                        exponent_sum <= exponent_sum + 1;
                    end else begin
                        z_mantissa <= new_mantissa[22:0];
                    end
                    counter <= 3'b011;
                end

                3'b011: begin

                    if (exponent_sum >= 9'h1FE) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};
                    end else if (exponent_sum <= 0) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h000000};
                    end else begin
                        z <= {a_sign ^ b_sign, exponent_sum[7:0], z_mantissa};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

