module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [3:0] SP;


always @(posedge Clk) begin
    if (Rst) begin

        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        SP <= 4;
        EMPTY <= 1;
        FULL <= 0;
    end else if (EN) begin
        if (RW == 0) begin 
            if (SP != 0) begin
                SP <= SP - 1;
                stack_mem[SP - 1] <= dataIn;
                EMPTY <= (SP - 1) == 4;
                FULL <= (SP - 1) == 0;
            end
        end else begin 
            if (SP != 4) begin
                dataOut <= stack_mem[SP - 1];
                stack_mem[SP - 1] <= 0;
                SP <= SP + 1;
                EMPTY <= (SP + 1) == 4;
                FULL <= (SP + 1) == 0;
            end
        end
    end
end

endmodule

