                stored_flag <= 0;
            end
        end else begin
            if (valid_in) begin
                data_lock <= data_in;
                stored_flag <= 1;
            end
        end


        data_out_next <= temp_data;
        valid_out_next <= temp_valid;


        data_out <= data_out_next;
        valid_out <= valid_out_next;
    end
