module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

    always @(*) begin
        r = 32'b0;
        carry = 1'b0;
        overflow = 1'b0;
        case (aluc)
            ADD: begin
                {carry, r} = {1'b0, a} + {1'b0, b};
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                {carry, r} = {1'b0, a} + {1'b0, b};
                overflow = 1'b0;
            end
            SUB: begin
                {carry, r} = {1'b0, a} - {1'b0, b};
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                {carry, r} = {1'b0, a} - {1'b0, b};
                overflow = 1'b0;
            end
            AND: begin
                r = a & b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            OR: begin
                r = a | b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            XOR: begin
                r = a ^ b;
                carry = 1'b0;
                overflow = 1'b0;
            end
            NOR: begin
                r = ~(a | b);
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLT: begin
                r = ($signed(a) < $signed(b)) ? 32'b1 : 32'b0;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLTU: begin
                r = (a < b) ? 32'b1 : 32'b0;
                carry = 1'b0;
                overflow = 1'b0;
            end
            SLL: begin
                integer shamt;
                shamt = a[4:0];
                r = b << shamt;
                carry = (shamt != 0) ? b[32 - shamt] : 1'b0;
                overflow = 1'b0;
            end
            SRL: begin
                integer shamt;
                shamt = a[4:0];
                r = b >> shamt;
                carry = (shamt != 0) ? b[shamt -1] : 1'b0;
                overflow = 1'b0;
            end
            SRA: begin
                integer shamt;
                shamt = a[4:0];
                r = $signed(b) >>> shamt;
                carry = (shamt != 0) ? b[shamt -1] : 1'b0;
                overflow = 1'b0;
            end
            SLLV: begin
                integer shamt;
                shamt = a[4:0];
                r = b << shamt;
                carry = (shamt != 0) ? b[32 - shamt] : 1'b0;
                overflow = 1'b0;
            end
            SRLV: begin
                integer shamt;
                shamt = a[4:0];
                r = b >> shamt;
                carry = (shamt != 0) ? b[shamt -1] : 1'b0;
                overflow = 1'b0;
            end
            SRAV: begin
                integer shamt;
                shamt = a[4:0];
                r = $signed(b) >>> shamt;
                carry = (shamt != 0) ? b[shamt -1] : 1'b0;
                overflow = 1'b0;
            end
            LUI: begin
                r = {b[15:0], 16'b0};
                carry = 1'b0;
                overflow = 1'b0;
            end
            default: begin
                r = 32'bz;
                carry = 1'b0;
                overflow = 1'b0;
            end
        endcase
    end

endmodule

