module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend_abs, saved_divisor_abs;
reg quotient_sign, remainder_sign;
reg [15:0] sr;
reg [3:0] cnt;
reg start_cnt;

wire [8:0] neg_divisor = {1'b1, ~saved_divisor_abs + 1};

always @(posedge clk) begin
    if (rst) begin
        saved_dividend_abs <= 8'b0;
        saved_divisor_abs <= 8'b0;
        quotient_sign <= 1'b0;
        remainder_sign <= 1'b0;
        sr <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        res_valid <= 1'b0;
    end else begin
        res_valid <= 1'b0;
        if (opn_valid && !res_valid) begin

            saved_dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            saved_divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            quotient_sign <= sign ? (dividend[7] ^ divisor[7]) : 1'b0;
            remainder_sign <= sign ? dividend[7] : 1'b0;

            sr <= {8'b0, saved_dividend_abs, 1'b0} << 1;
            cnt <= 4'd1;
            start_cnt <= 1'b1;
        end else if (start_cnt) begin
            if (cnt < 4'd8) begin

                wire [8:0] sub_result = {1'b0, sr[15:8]} + neg_divisor;
                if (sub_result[8]) begin

                    sr[15:8] <= sub_result[7:0];
                    sr <= {sr[14:0], 1'b1};
                end else begin

                    sr <= {sr[14:0], 1'b0};
                end
                cnt <= cnt + 1;
            end else begin

                result <= {remainder_sign ? -sr[15:8] : sr[15:8], quotient_sign ? -sr[7:0] : sr[7:0]};
                res_valid <= 1'b1;
                start_cnt <= 1'b0;
            end
        end
    end
end

endmodule

