module fixed_point_adder #(
    parameter Q = 16,
    parameter N = 32
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];

    always @(*) begin
        if (a_sign == b_sign) begin

            wire signed [N-1:0] sum = a + b;
            res = sum;

            if (a_sign) begin

                if (sum[N-1] == 0) res = {1'b1, {(N-1){1'b1}}};
            end else begin

                if (sum[N-1] == 1) res = {1'b0, {(N-1){1'b0}}};
            end
        end else begin

            wire [N-2:0] abs_a = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
            wire [N-2:0] abs_b = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];
            wire [N-1:0] diff;

            if (abs_a > abs_b)
                diff = {1'b0, abs_a} - {1'b0, abs_b};
            else if (abs_b > abs_a)
                diff = {1'b0, abs_b} - {1'b0, abs_a};
            else
                diff = 0;

            res = (abs_a > abs_b) ? {a_sign, diff[N-2:0]} :
                  (abs_b > abs_a) ? {b_sign, diff[N-2:0]} :
                  {1'b0, {(N-1){1'b0}}};
        end
    end

    assign c = res;

endmodule

