module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    localparam PTR_WIDTH = 4;
    reg [PTR_WIDTH-1:0] wptr_bin, rptr_bin;
    wire [PTR_WIDTH-1:0] wptr_gray, rptr_gray;

    assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
    assign rptr_gray = (rptr_bin >> 1) ^ rptr_bin;


    reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync <= rptr_gray_sync1;
        end
    end

    function [PTR_WIDTH-1:0] gray2bin;
        input [PTR_WIDTH-1:0] gray;
        reg [PTR_WIDTH-1:0] bin;
        integer i;
        begin
            bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
            for (i = PTR_WIDTH-2;
 i >= 0;
 i = i-1)
                bin[i] = gray[i] ^ bin[i+1];
            gray2bin = bin;
        end
    endfunction

    wire [PTR_WIDTH-1:0] rptr_sync = gray2bin(rptr_gray_sync);


    reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync <= wptr_gray_sync1;
        end
    end

    wire [PTR_WIDTH-1:0] wptr_sync = gray2bin(wptr_gray_sync);

    wire wfull, rempty;
    assign wfull = (wptr_gray[3] != rptr_sync[3]) && 
                   (wptr_gray[2] != rptr_sync[2]) && 
                   (wptr_gray[1:0] == rptr_sync[1:0]);
    assign rempty = (rptr_bin == wptr_sync);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_bin <= 0;
        end else if (winc && !wfull) begin
            wptr_bin <= wptr_bin + 1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_bin <= 0;
        end else if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
        end
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin[$clog2(DEPTH)-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin[$clog2(DEPTH)-1:0]),
        .rdata(rdata)
    );

endmodule

