    if (Rst) begin
        SP <= 3'b100;
        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        dataOut <= 4'b0;
    end else if (EN) begin
        if (!RW) begin 
            if (SP != 0) begin
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end
        end else begin 
            if (SP < 4) begin
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0;
                SP <= SP + 1;
            end
        end
    end
end

