module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

localparam idle      = 2'd0,
           s1_red    = 2'd1,
           s2_yellow = 2'd2,
           s3_green  = 2'd3;

reg [1:0] state;
reg [7:0] cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s3_green;

            s3_green: begin
                if (cnt == 0) state <= s2_yellow;
            end
            s2_yellow: begin
                if (cnt == 0) state <= s1_red;
            end
            s1_red: begin
                if (cnt == 0) state <= s3_green;
            end
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
    end else begin
        if (pass_request && (state == s3_green) && (cnt > 8'd10)) begin
            cnt <= 8'd10;
        end else if (state == s3_green && cnt == 0) begin
            cnt <= 8'd5;

        end else if (state == s2_yellow && cnt == 0) begin
            cnt <= 8'd10;

        end else if (state == s1_red && cnt == 0) begin
            cnt <= 8'd60;

        end else begin
            cnt <= cnt - 1'b1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red    <= 1'b0;
        yellow <= 1'b0;
        green  <= 1'b0;
    end else begin
        case (state)
            s3_green: begin
                green  <= 1'b1;
                yellow <= 1'b0;
                red    <= 1'b0;
            end
            s2_yellow: begin
                green  <= 1'b0;
                yellow <= 1'b1;
                red    <= 1'b0;
            end
            s1_red: begin
                green  <= 1'b0;
                yellow <= 1'b0;
                red    <= 1'b1;
            end
            default: begin 
                green  <= 1'b0;
                yellow <= 1'b0;
                red    <= 1'b0;
            end
        endcase
    end
end

assign clock = cnt;

endmodule

