module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg sign_dividend;
    reg sign_divisor;
    reg [7:0] remainder_unsigned;
    reg [7:0] quotient_unsigned;
    reg [15:0] result_reg;

    assign result = result_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            remainder_unsigned <= 0;
            quotient_unsigned <= 0;
            result_reg <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    sign_dividend <= dividend[7];
                    sign_divisor <= divisor[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    sign_dividend <= 0;
                    sign_divisor <= 0;
                end

                SR <= {abs_dividend, 8'b0} << 1;
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && cnt < 8) begin

                SR <= SR << 1;
                if (SR[15:8] >= abs_divisor) begin
                    SR[15:8] <= SR[15:8] - abs_divisor;
                    SR[0] <= 1;
                end else begin
                    SR[0] <= 0;
                end
                cnt <= cnt + 1;
            end else if (start_cnt && cnt == 8) begin

                remainder_unsigned <= SR[15:8];
                quotient_unsigned <= SR[7:0];
                start_cnt <= 0;
                cnt <= 0;

                result_reg <= (sign) ? { (sign_dividend ? (~remainder_unsigned + 1) : remainder_unsigned),
                                         ( (sign_dividend ^ sign_divisor) ? (~quotient_unsigned + 1) : quotient_unsigned ) } : {remainder_unsigned, quotient_unsigned};
                res_valid <= 1;
            end
        end
    end

endmodule

