module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg sign_a, sign_b;
reg [N-1:0] a_mag, b_mag;
reg [N-1:0] res;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];


    a_mag = sign_a ? (~a + 1) : a;
    b_mag = sign_b ? (~b + 1) : b;

    if (sign_a == sign_b) begin

        res = {sign_a, (a_mag + b_mag)[N-2:0]};
    end else begin

        if (a_mag > b_mag) begin
            res = {sign_a, (a_mag - b_mag)[N-2:0]};
        end else if (b_mag > a_mag) begin
            res = {sign_b, (b_mag - a_mag)[N-2:0]};
        end else begin

            res = {1'b0, {(N-1){1'b0}}};
        end
    end

    c = res;
end

endmodule

