    reg a_sign, b_sign;
    reg [N-2:0] a_mag, b_mag;
    reg same_sign;
    reg [N-1:0] same_res;
    reg [N-1:0] diff_res;
    reg same_res_sign, diff_res_sign;

    a_sign = a[N-1];
    b_sign = b[N-1];
    a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

    same_sign = (a_sign == b_sign);

    if (same_sign) begin
        same_res = a - b;
        if (same_res == 0) begin
            same_res_sign = 0;
        end else begin
            same_res_sign = a_sign;
        end
        res = {same_res_sign, same_res[N-2:0]};
    end else begin
        reg [N-1:0] a_abs, b_abs, sum_mag;
        a_abs = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
        b_abs = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];
        sum_mag = a_abs + b_abs;

        if (a_sign == 0) begin 
            diff_res_sign = (a_abs >= b_abs) ? 1'b0 : 1'b1;
        end else begin 
            diff_res_sign = (a_abs >= b_abs) ? 1'b1 : 1'b0;
        end

        if (sum_mag == 0) begin
            diff_res_sign = 1'b0;
        end

        res = {diff_res_sign, sum_mag[N-2:0]};
    end
end

assign c = res;

