module float_multi (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa;
    reg [8:0] a_exponent, b_exponent;

    reg a_sign, b_sign;
    reg [49:0] product;
    reg guard, round, sticky;
    reg [23:0] z_mantissa;
    reg [8:0] z_exponent;
    reg z_sign;

    wire [31:0] abs_a = a[30:0];
    wire [31:0] abs_b = b[30:0];
    wire a_sign = a[31];
    wire b_sign = b[31];
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);
    wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
    wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
    wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
    wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 0);
    wire [22:0] a_mant = a_mantissa[22:0];
    wire [22:0] b_mant = b_mantissa[22:0];

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
        end else begin
            case (counter)

                3'd0: begin
                    counter <= 3'd1;

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_mantissa <= (a_exponent == 9'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b_exponent == 9'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                end


                3'd1: begin
                    if (a_is_nan || b_is_nan) begin
                        z <= 32'h7FC00000;

                    end else if (a_is_inf) begin
                        if (b_is_zero) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                        end
                    end else if (b_is_inf) begin
                        if (a_is_zero) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                        end
                    end else if (a_is_zero || b_is_zero) begin
                        z <= {a_sign ^ b_sign, 31'd0};

                    end else begin
                        counter <= 3'd2;
                    end
                end


                3'd2: begin
