                        z <= {a_sign ^ b_sign, 31'd0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 3'd0;
                end

                default: counter <= 3'd0;
            endcase
        end
    end

endmodule

