module sub_64bit (
    input signed [63:0] A,
    input signed [63:0] B,
    output reg signed [63:0] result,
    output reg overflow
);

always @(*) begin

    result = A - B;


    overflow = ((~A[63] & B[63] & result[63]) | (A[63] & ~B[63] & ~result[63])) ? 1'b1 : 1'b0;
end

endmodule

